/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170228-7","meetingId":"h29-cm02","date":"2017年2月28日","dateIso":"2017-02-28","committee":"厚生委員会","time":"午前１０時００分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"臨時福祉給付金（経済対策分）の実施","agenda":"臨時福祉給付金（経済対策分）の実施","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"前回が５万２,１４３人で、この点を１つ、理由がはっきりしているのであれば教えてください。単純計算するとそうなるんですけれども、この理由は何があるのか説明を求めました。","respondent":"大串福祉計画課長","answer":"同様に秋のほうも、当初見込んでいたのは、やはり５万１,０００人ぐらいと記憶をしております。本日で一旦は終了という形になりますけれども、まだ今後、３月中にも支給を行う予定になっております。","id":"exchange-001"},{"speaker":"浅野委員","kind":"質問","question":"そういう場合には、あなたは非該当でしたという形で、ご本人にお知らせをされるのが普通だと思うのですけれども、それはどのような形で行われるのか。それと、今回の給付金の作業の中で大体何件ぐらいあるのかというのが、もしわかれば説明を求めました。","respondent":"大串福祉計画課長","answer":"そうした中で、最終的に支給の対象にはならないという方が出てまいります。その発生数といいますか、発生率については、なかなか把握するのは難しいかと考えています。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"３月２１日には広報しながわで、受付終了が９月の１５日で、受付の具合によってそういうことを考えられているのか。この期間の中で一番ピークを迎える時期というのでしょうか、そういうものがあれば説明を求めました。","respondent":"大串福祉計画課長","answer":"したがいまして、９月まで何もやらないということではありません。そういった何らかのこちらからの働きかけがあった後には、やはり申請件数が伸びてきているです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４番のところの実績なのですけれども、ここはどこの職員がどんな体制でされるのかということも教えてほしいと求めました。ＤＶの方は住所は知らせないでほしいというふうにされている方も多いと思うのですが、そこのところがわかったら説明を求めました。","respondent":"大串福祉計画課長","answer":"秋のほうは３,０００円ですので７０％前半ぐらいかなと見込んでおります。個別に対応していますので、ただ、そこで今まで何かトラブルというのは、私の耳には入っていないところです。","id":"exchange-004"}]},{"id":"topic-02","title":"ゆうゆうプラザの拡大","agenda":"ゆうゆうプラザの拡大","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"平成３１年ということで、まだ２年ぐらい先ということで、こちらは２つとも浴室はないのですか。その点はぜひとも気をつけながら、近隣に配慮しながら行ってほしいと求めましたので、この点を説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"解体工事につきましても同じように近隣の方々に説明をさせていただき、きちんとした交通誘導員を配置するなどの配慮をしています。今後、近隣に対しても説明するときには、十分に安全に配慮してまいります。","id":"exchange-005"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認をさせてください。より高齢者の方と子育て世代の方の触れ合いですとか、こちらは入り口を分けた理由がございましたら説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"私どもも、入り口をできれば１つにしたかったのですけれども、狭い敷地の構造上、バギー置き場をどこにするだとかいうこともございまして、構造上考えた結果、入り口がどうしても別々にせざるを得ないということになってしまった結果です。","id":"exchange-006"},{"speaker":"横山委員","kind":"質問・要望","question":"構造上の理由ということでお伺いをいたしました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ボランティアの方が４人で、その体制と中身について、どのようなものになるのかというのを教えてほしいと求めました。お茶飲みができて、おしゃべりができるような、そういう場所をすごくつくってほしいという要望を受けるのですけれども。","respondent":"松山高齢者地域支援課長","answer":"お尋ねの１点目が、地域ミニデイのことですけれども、先ほど説明しました園芸療法を活用した認知症予防とは別なものです。大崎で実施しているモデルというのを継承しまして、どのような体制でやったらいいかというのを今、法人と協議している最中です。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、地域の方がふらっと寄れて、お茶を飲みながらおしゃべりできるみたいなのは、場所としては２階になるのでしょうか。２階でやるのか、園芸療法で認知症予防は、介護保険のサービスとのかかわりではどういうものになるのかということも教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"こちらは週に１回程度なので、常時ということではございませんので、こういった事業によって１階を使うか２階を使うかという形になってまいります。","id":"exchange-009"},{"speaker":"安藤副委員長","kind":"確認","question":"そういった地域の町会からの声とかというのは、区としては伺っているかどうか伺います。平塚シルバーセンターの時代には浴室はなかったのかというのを確認でお伺いするのと、どのような規模の対象で行うのか、お伺いします。","respondent":"松山高齢者地域支援課長","answer":"地域への説明会ですが、３月２日に近隣への説明会というのを予定しています。同じ日に、当該町会の方、あるいは近隣の町会の方、連合町会長の方、高齢者クラブの方にも予定をしています。","id":"exchange-010"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"そうした方の利用というのはこれまでどおり、シルバーセンターと同様に無料で使えるのかどうかということの確認を、１つお願いします。地域からの要望があるところというのは、そういった要望があれば、お伺いします。","respondent":"松山高齢者地域支援課長","answer":"歩いて通えるような居場所というのは必要だと考えておりますので、可能性があれば、ゆうゆうプラザというのを展開していきたいと考えています。ただ、老朽化の程度ですとか、ご利用者の困り具合を総合的に考えて、今後進めていければと思っています。","id":"exchange-011"}]},{"id":"topic-03","title":"後期高齢者医療制度の保険料軽減特例の見直し","agenda":"後期高齢者医療制度の保険料軽減特例の見直し","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めてお伺いしたいと思うのですけれども、後期高齢者が平成２９年度だと何人くらいになるのかということを、１点お聞かせください。２０万円以下、５８万円以下、その方々がおおよそどれぐらいの値上げになるのかということについても説明を求めました。","respondent":"高森国保医療年金課長","answer":"２０万円以下の方につきましては３６７人、５８万円以下の方につきましては２,７８４人が影響を受けると考えています。１人当たりということで、２０万円以下の方につきましては４,４００円ほど、５８万円以下の方については９,９００円ほどです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１５万円以下のところでは５０％、その負担については、どこがどういうふうに負担をしているのかということもお聞かせほしいと求めました。あったらどんな形なのかというのがわかったら、教えてほしいと求めました。","respondent":"高森国保医療年金課長","answer":"２億３,２００万円ほどですが、一般会計からの繰り出しをしておりますので、これを充ててあります。他都道府県の独自の軽減策ですが、東京都以外にはないというふうに、私の知り得ているところでは、そのようなところは承知しておりません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この軽減措置だけで２億３,２００万円ということなのか、そのところはお聞かせほしいと求めました。その収入が少ないほうの保険料になりますよという感じで書かれているのですけれども、そういうことも含めてご説明をいただけたらと思います。","respondent":"高森国保医療年金課長","answer":"枠の中の説明をですが、軽減割合が変わってまいりますけれども、１番に均等割額の軽減ということで表があります。被保険者の方の有利なほうを選択する形で現在も行っておりますし、これからもそういう対応をしていくです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そういうことがここに書かれているのだなと思ったのですけれども、そういうことでいうと、それを除いて７７２名が１割負担から３割負担になるということで考えていいのか、このことだけ確認させてください。","respondent":"高森国保医療年金課長","answer":"平成２８年９割から７割に変更になりますけれども、これがずばりその人に当てはまるのか、もしくは１番のほうに該当するかどうかです。収入に応じた形になりますので、申し上げているとおり、被保険者の有利なほうを選択するという形で制度は動いていくと理解しております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういうふうに軽減を希望するかというところが出ていまして、いろいろあるのですけれども、品川区としてはどういう希望をされたのかについて説明を求めました。","respondent":"高森国保医療年金課長","answer":"確かに保険料の独自軽減に対する意向調査というのは、東京都後期高齢者医療広域連合から６２の市町村に対して行っております。品川区においては、現行の独自軽減の継続を希望するというところで、希望はお出ししています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。そこは変わらないのか、改めてそのところを強く要望していただきたいと思うのですけれども、その点をお伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"今までも東京都後期高齢者医療広域連合を通しまして、国に対して、この軽減については必要だということで要望は出してきてあります。必要だという認識ではおりますので、周りの制度をさまざまな形で、最終的にはそういうものも勘案しながら進めていきたいと考えているところです。","id":"exchange-017"}]},{"id":"topic-04","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"塾や習い事は週２日程度だから、月１０日としているということですけれども、もうちょっと詳しくお聞かせいただきたい。３点目が、モニタリング時に訪問して、これがどういうことなのかということについてお聞かせいただきたいということです。","respondent":"中山障害者福祉課長","answer":"そのため、こちらの別表の中にも、学校終了後の支援の場として、週２日を基本としています。ケアプランの６カ月ごとの見直しの際に、事業所がどのような支援をお子さんたちにしているか、そうしたところを見させていただいています。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"必要な量を決定していくということなのですが、そうすると、別表の１０日というのはなくなるということで考えていいのでしょうか。その子どもに必要な量を、勘案事項に基づいて決定していくという、そういうやり方に変わるのかということをお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"別表の１０日というのは残すつもりでおります。そうした形で対応していければと考えています。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、ここの要綱では、支給決定基準の上限は別表のとおりということなのですけれども、別表の規定というのは、要綱の中ではどういうふうに規定されるのか、また別な形での１０日という表現をつくられるのかというのはどうなるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"今ちょうど見直しの最中なので、１人当たりの１カ月の支給決定基準の上限はというふうになっているのですが、こちらは削除になると思っています。ここについては、お子さんの状況に応じて支給をしていくということがあれば、そのままで使えるのではないかと考えているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１週間に２日程度ということが基本という考え方になっていきますので、必要な量を支給するという形にすべきなのではないかと思うのです。そういうところでどうかというところを、私は改めていただきたいと思うのですけれども、その点はいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"そういうこともご説明する中で、ほとんどの親御さんにつきましてはご理解いただき。逆にそこでの支援にちぐはぐさがあったり、そのご家庭の状況には合わせて、そのような対応とさせていただきたいと考えています。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところが、私は放課後等デイサービスに求められていると思うのです。１０日という日にちを基本にするというところも、ぜひ改善させていただきたいということで、強く要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"安藤副委員長","kind":"質問","question":"結果として、これは差別解消法からも、私は違反しているのではないかという現状があると思うのです。どう考えているのかということと、この改善というのが必要だと思うのですが、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"そこについては４月以降、新たなところで人員配置も整えて、そうした就労支援もやっていくつもりでいます。きっとここでの問題点なのかなと考えていますので、障害のあるお子さんもないお子さんも、今後も対応していきたいと考えているところです。","id":"exchange-023"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"多様なかかわりをつくれる環境が選べるような、親が自分の子どもをどういった場所で豊かに育っていってほしいかということを選べるような環境を。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374035?Template=document&Id=3470#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":27300,"voices":69}},{"id":"h29-20170228-8","meetingId":"h29-cm02","date":"2017年2月28日","dateIso":"2017-02-28","committee":"建設委員会","time":"午前１０時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件整理しています。","topics":[{"id":"topic-01","title":"大森駅水神口地下機械式駐輪場の開設","agenda":"大森駅水神口地下機械式駐輪場の開設","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"先ほど見せていただいて、今受付けを開始して１９６名ということでした。全部で７６５台が入るので、１,０００台近くになるわけですけれども、ずっとあのままになるのでしょうかということをちょっと伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"駐輪台数につきましては、総計で１,４０５台となってまいりますけれども、今後また上層部の駐輪場のほうのラックの改修等も進めてまいりますので。やはり人口増加だとか、バスから自転車等への変更等も考えられますので、約１,１００台ほどは必要ということになっております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"何かもっとじゃんじゃん来るのかなというイメージがあったのですが、まだ１９６人程度なのだと感じたので、ちょっと聞かせていただきました。駅前住宅の駐輪場については、今後の変化ということなのですけれども、今後の変化によって撤去する可能性もあるということにもなるのかを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"桜の時期の目黒川の通航マナー啓発・対策の実施","agenda":"桜の時期の目黒川の通航マナー啓発・対策の実施","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"何で翌週が入らなかったのか、８日、９日。もう今年は決まってしまったのだったら、来年に向けてその辺はどう考えているか説明を求めました。","respondent":"和田河川下水道課長","answer":"これについては、便宜的に今回は桜が満開になりそうな１日、その前の週の３月２５日（土）から４月９日（日）まで２週間ずっとやるつもりでおります。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"問題になっている写真にあるような行為、これはどのぐらい問題になっているのか。クレームもどのぐらい来ていて、対策1)では、品川区はどこまでできるものなのでしょうかということをまずお聞きしたいと思います。","respondent":"和田河川下水道課長","answer":"舟運事業者から、それから周囲にお住まいの方から騒音がひどいということで、３件ほどのクレームをいただいているところです。法令上、今回我々は基本的には通航マナーを啓発するという名目で、河川占用を行うというような位置づけでやるものです。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"品川区はやりづらいのだろうと思うのだけれども、品川区では、そういう罰則規定とかというのはつくれないのですか。は品川区の中で罰則規定であるとか、そういうものを何とかつくれないのかなと思うのですが、いかがか尋ねました。","respondent":"和田河川下水道課長","answer":"具体的には、今年中に何かしらの発信をするということで、警視庁のほうで現在検討が進められているというふうに聞いています。同様に海上保安庁と警視庁、それから東京都の三者で独自のルールがつくれないかという検討会も発足していますので、我々としましては。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜかというと、やはり危ない。可能かどうかはいろいろ考えてほしいと求めました。","respondent":"和田河川下水道課長","answer":"我々行政として、その人を止めて注意する権限はございませんので、それはできないということを申し上げておきます。委員ご指摘のように強い態度に出ても大丈夫なのかなというような状況が見られましたら、来年につなげていきたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"対策2)の横断幕の設置についてなのですが、このとおりになるのかどうかはわからないですけれども、観光地として取り組んでこられたところもあると。その景観との配慮というか関係、委員会の中でも議論されているところはどの程度あるのか、お伺いしたいと思います。","respondent":"和田河川下水道課長","answer":"今回２週間、基本的にはこれでいいということで、舟運事業者から了解を得ているところです。我々この対策2)の枠にありますように、この白色にしているようなもので、一応配慮をしたというような状況で整理をさせていただいているところです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。十分配慮しながらということは伺いましたけれども、バランスというものを考えながら進めていただきたいなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"意見","question":"そもそも水上の法令がなかったり、また取り締まり条例の実効性がなかったりという、水上のそういったルールが緩いのはなぜなのか。飲酒をしてもいいし、スピード制限もないというのは、そもそも何でなのかなという疑問ですとの意見を述べました。","respondent":"和田河川下水道課長","answer":"私が答えるのが適当かどうかわかりませんけれども、実効性がない水上取締条例でやれてきたという状況ではないのかなというふうに感じます。水質も良くなり、そういう船が増えてきたということから、危ないという声が上がってきたという状況だと思います。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"意見","question":"水質のことに関してなのですが、水質が良くなってきているということなのですが、走る皆さんは水上バイクだとわーっと顔にも浴びるわけですよね。そういった場合でも害がない水質になっているということでいいのですよねとの意見を述べました。","respondent":"和田河川下水道課長","answer":"それについては環境基準を下回っておりますので、目黒川の水質は環境基準上は問題ないというふうに言えるかと思います。ただ、あの水をがぶがぶ飲めるかというと、そうではないということです。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"その団体は大田区とか港区、当然品川区にもあると思うのですけれども、そういった他区の団体にもお声をかけているということで認識してよろしいのか尋ねました。","respondent":"和田河川下水道課長","answer":"ビブスというのですかね、それを交付して、そのビブスがないと給油できないというような自主的な取組みをやっていらっしゃる団体もあります。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望です。設置期間が本年の１月３０日からということで、約１ヶ月経過しましたけれども、今まで１ヶ月経った中でありましたら教えてほしいと求めました。","respondent":"和田河川下水道課長","answer":"安全通航を阻害するような船なり水上バイクが存在したかというと、存在した事実はございません。問題といいますと、その設置して撮れる画面の角度とかズームアップのズーム度というのですか、そういうものについての調整を細かく今現在しています。","id":"exchange-012"}]},{"id":"topic-03","title":"続きまして、(3)東品川二丁目防災桟橋の整備","agenda":"続きまして、(3)東品川二丁目防災桟橋の整備","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これはコスト、予算というか、当然待合所は都有地であるので、建物を建てるとき、品川区が出すのでしょうか、東京都が出すのでしょうか。それから、工事のほうも含めて財源はどこから来ているのか説明を求めました。","respondent":"和田河川下水道課長","answer":"全て品川区の区費になります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"でもこれは東京都の整備計画にも入っているものだと思うのですが、そこは何割かの助成金とかというのはないものなのでしょうか。ちょっと考え方というか、それを説明を求めました。","respondent":"和田河川下水道課長","answer":"例えば今回の東品川二丁目防災桟橋については、清掃作業所の桟橋がもはやあるという状況です。これは使い勝手が悪いということで、区独自の判断でこういう小型船舶が着岸できるような浮桟橋を独自につくったという整理になってあります。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"運航上の支障とか、そういったものはないのかどうか、以上２点をお伺いします。","respondent":"和田河川下水道課長","answer":"そういうところで舟運事業者から自由な発想でこれからもどんどんと手が挙がってくるものと考えられます。それから２点目のクリスタルヨットクラブとの航行の安全の関係ですが、ここでいいという承諾は得られて設置しているものです。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そことの仕事に影響がないように、そこら辺は舟運事業者にはよく通知しておいてもらいたいと思います。その辺がちょっと気になるので、邪魔にならないようにということをそこだけお願いして、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-04","title":"避難勧告等の伝達手段について（目黒川氾濫、津波、土砂災害）","agenda":"避難勧告等の伝達手段について（目黒川氾濫、津波、土砂災害）","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"配信登録の受付に関してですが、こちらの作業的にはどういう形をとっていくのか、そこだけちょっと確認をしたいと思います。","respondent":"古巻防災課長","answer":"もう一つは、ご自身で携帯電話等を使いまして、インターネットの画面上で登録をするというような形を考えてあります。その二通りで登録を進めるというような流れになります。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然区のほうですから、そういうリストの大事さは十分わかっていると思います。その辺だけ気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"塚本委員","kind":"確認","question":"これは返信があれば相手に伝わったということで一つ確認ができるのですけれども、繰り返しでそのままずっと永遠にというか、やり続けるだけなのか。どうなっているのかわからないというところに対して何か対応がされていくというか、繰り返して返信が来なかった場合のことをお伺いしたいと思います。","respondent":"古巻防災課長","answer":"現時点では永遠に繰り返すということは考えておりませんで、そこで伝わったものとして判断するということで考えております。例えば５回なり１０回なりというところで区切って配信をストップするというような形になります。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"身体に少々不具合があるとかという場合に、そういう方についての繰り返しの後の無反応についての考え方みたいなものもちょっと配慮ができればありがたいのかなと思うのですけれども、その辺はどのようにお考えか尋ねました。","respondent":"古巻防災課長","answer":"そういった配慮が必要な方につきましては、別の手段といいましょうか、いわゆる要配慮者の避難の個別計画の中で十分に対応するとかといった形で漏れのないように進めていきたいというふうに考えております。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"今の質疑に関連してですけれども、やはり要配慮者の把握が必要なのではないかなと思うのですね。こちらからどうですかというようなお声かけなどは、要配慮者としての登録というのですかね、考えはないのか伺いたいと思います。","respondent":"古巻防災課長","answer":"町会等へ個別に説明に入る予定にしておりますので、それから区のほうでは名簿もできておりますので、その辺りで十分要配慮者への周知が進むように進めていきたいと思います。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その個別の対応というのですか、対応がとられるようになるのでしょうか、そうしていただきたいのですけれども。誰が迎えに行って、誰と一緒に避難してとか、そういうのは決められているのか尋ねました。","respondent":"古巻防災課長","answer":"避難所の緊急通知コール、今ご報告差し上げたものがあるなしにかかわらず進めていくということで、区では取組みをしています。まだ１００％というところまではいきませんけれども、これは従前と変わらない考え方で進めていきたいというふうに思います。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとやはり言葉の意味というのでしょうか、そういうのがこの情報はどこまで自分が動くものなのかというのがわかるようにはされているのでしょうか。ちょっと細かいですけれどもそういった周知も必要ではないかなと思いますが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"避難情報の意味、それによって十分に周知が図れるように進めてまいりますので、一人ひとりに伝わるような形で周知を進めていきたいと思います。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり全ての皆さん、避難できない方がいないようにしていかなければいけないし、避難していただかなければいけないものなので、そこは丁寧に、慎重に細かにやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"組織上の問題もあると思うのですけれども、どういう形になっているのでしょうか。そこを集約して、通知をしなさいというふうに、どのような流れになっているのか尋ねました。","respondent":"古巻防災課長","answer":"避難準備情報が出れば、それに沿って自動で、そこの間に判断は入りません。避難情報が出れば配信をするという流れになります。","id":"exchange-025"},{"speaker":"西本委員","kind":"確認","question":"そういう場合のメールとか電話、この電話の場合というのは登録するときに携帯なのでしょうか、固定電話になるのか。そこの通信所を使えるのかとか、混線とかしてなかなかつながらないとかということはどうなのでしょうか、確認をされているのか尋ねました。","respondent":"古巻防災課長","answer":"まずはシステム上の流れでメールが行きますので、電話がいきなりいくよりは、比較的情報の到達はしやすいかなと思います。よりいろいろな手段を使いまして周知はきちんとできるように情報発信を進めていきたいと思います。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"それで受け取りましたという確認操作が入りますよね。その辺をどこまで確認されて、９割方大丈夫ですよとかと、そういう確認というのはどのぐらいまでされているのか尋ねました。","respondent":"古巻防災課長","answer":"１００％これで情報周知を確実にするというところは、より迅速に情報をお知らせして、適切な避難行動がとれるようにということで進めているものです。そのようにご理解いただければというふうに思います。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そこはどうやったら確認できるのかなというところはありますが。いろいろと有効活用できるのではないかなと思うのですが、今後の研究課題としていただきたいなと思いますが、いかがか尋ねました。","respondent":"和田河川下水道課長","answer":"そういう意味では、居住されている方に関しましては、そういう講習内での周知というのは基本的には図られていると。重層的にこういうことを周知することによって避難を促すということを考えているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"もちろん避難情報緊急通知コール以外の伝達手段、区の車が回ったり、防災スピーカーでのアナウンスは当然やられるということでよろしいのでしょうか。その確認を１点、お願いします。","respondent":"古巻防災課長","answer":"３、４でもお伝えをしていますが、比較的範囲が限られた方に対して直接的に情報をお知らせするという趣旨で今回サービスを始めるものです。防災行政無線でありますとか広報車を使っての周知、そういったもので広く周知をしていくということは今までと変わらないところです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、公園しか挙がっていないのですけれども、ほかの住居とかは対象とされていないという理解でよろしいのでしょうか。ちょっとこの理解というか、どういうふうにこの資料を読んだらいいのかちょっとわからなかったもので、その辺の解説をお願いします。","respondent":"和田河川下水道課長","answer":"ですから、品川区としましては、T.P.＋3.5ｍの護岸で守られておりますので、基本的には津波は陸地には到達しない。緩傾斜護岸だったり、そういうところに人がいらっしゃると危ないので、そこを避難指示の対象場所ということで指定をさせていただいたところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"ということは、この注意報の発令時、この公園の場合に限っては、配信登録とかそういった話は今回は関係ないという理解でよろしいのか尋ねました。","respondent":"古巻防災課長、和田河川下水道課長","answer":"別添資料３で言いますと、かつ水門が閉まらなかった状態とか、こちらの方に対して津波警報の際にメール等でお知らせをするという流れです。説明が不足しまして申し訳ございませんでした。 この津波注意報が発令される公園につきましては、注意報が発令された段階で区の施設に関しましては閉鎖をするということで考えております。都立の公園につきましては、閉鎖を呼びかけるということを考えているところです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"わかりました、ありがとうあります。多数の人が来られるので、あらかじめ周知等を行ったほうがよろしいかと思うのですけれども、そのあたりのお考えはどうか尋ねました。","respondent":"古巻防災課長","answer":"周知に関しましては、今回の通知コールの周知はホームページそれから広報しながわ等でも行いますし、それに合わせまして、こういった避難基準等を広くお知らせをするということは必要なことだと思いますので、引き続き取り組んでまいりたいというふうに思います。","id":"exchange-032"}]},{"id":"topic-05","title":"大崎駅周辺地域都市再生緊急整備協議会設立","agenda":"大崎駅周辺地域都市再生緊急整備協議会設立","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"今回大崎駅周辺ということなのですけれども、大崎駅、五反田駅、ほかにも品川区には大規模な駅があると思いますけれども、ほかの駅も同様に今後やられる予定というのはあるのか尋ねました。","respondent":"古巻防災課長","answer":"現在、大井町駅周辺それから目黒駅周辺につきましては既に協議会が立ち上がっておりまして、帰宅困難者対策を進めているところです。は徒歩帰宅者の対策ということで、国道１５号線の徒歩帰宅者の対策の協議会、こちらは既に立ち上がって計画策定、訓練等を進めているところです。","id":"exchange-033"},{"speaker":"高橋（伸）委員","kind":"質問","question":"６９名ということで、２回目以降もやはり６９名の方が構成していくのか、あるいはもう少し増員をして計画を策定していくということでよろしいのか。その辺の人数、今後２回目以降を説明を求めました。","respondent":"古巻防災課長","answer":"ですから、先ほどお話ししたように計画部会として２５名の方の名簿がありますので、こちらの２５名の方を中心に作成を進めていくというような形です。あまりたくさんで会議を何回もやるということではなく、比較的絞った形で実作業を行っていくような形を考えてあります。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"大崎駅周辺地域都市再生緊急整備の緊急整備という言葉が、これは特別何か急ぐよというか、大井町とか目黒とかも同じようにこういった形でやられてきたのかどうかというところを含めてなのですけれども、緊急整備という言葉に関して何か特別説明するようなことがあれば教えていただけますか。","respondent":"古巻防災課長","answer":"どうしてもそれに結びついて急いで防災対策を進めなければいけないというようなイメージを持たれるのかなと思うのですが、都市計画を緊急に進めなければならないというような、緊急という言葉は防災と直接結びつくものではありません。","id":"exchange-035"},{"speaker":"塚本委員","kind":"意見","question":"大崎についても前々から帰宅困難者についての課題というのは指摘をしてきたこともありましたし、ほかからもいろいろ指摘があったと思うのですね。もう少し早くできるようなことが、この時期にようやく立ち上がってきたことに対する一つの評価というか、思いを説明を求めました。","respondent":"古巻防災課長","answer":"順次活動が開始できるところから進めてきておりまして、区としましても対策を進めていける道筋がある程度見えてきたというところがあります。時間がかかるかと思いますが、気持ちを引き締めまして進めていきたいと考えていますので、よろしくお願いいたします。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"それで今回、大崎が何番目となるのですか、それとも大崎がこういう形でというふうになったのでしょうか。ちょっとほかの地域のところの進捗状況も含めて教えていただきたいのですけれども。","respondent":"古巻防災課長","answer":"帰宅困難者対策協議会をいきなりある意味立ち上げて帰宅困難者対策を始めたですので、大崎駅、五反田駅周辺以外にこういった手法で進めているところはございません。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"だから、地域の再生という大きな括りの中では、大崎が指定されてやりなさいよという形なのでしょうか。なぜ大崎駅というところでこういうのが出てきてという、それはどういうふうに考えたらよろしいのか尋ねました。","respondent":"古巻防災課長","answer":"まずそこの全体の都市計画というか、防災対策を都市再生安全確保計画という名前で作成をする手順を踏む必要があるです。それに基づいて、ちょっと構成上のいろいろな決まりで大崎地域だけ少し特殊な形の進め方になっているとご理解いただければと思います。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"そういう人たちは構成員の中に入れないのでしょうか。それが気になったところなのですが、それはどうなのか尋ねました。","respondent":"古巻防災課長","answer":"構成員に関しましては、こちらの資料にあるとおりですけれども、地域の方につきましてはオブザーバーという形でご参加をお願いしています。ですので、ご意見を伺いながら、それを取り入れて進めていくというような流れにはなってあります。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"専門的な考え方というのは当然必要になってくると思うのですが、オブザーバーという意味合いはどうなのでしょうか。必ず町会長とかにお伺いがかかって、ちょっとこの進め方について、どういう進め方を想定されているのかなと思います。","respondent":"古巻防災課長","answer":"進め方に関しましてはオブザーバーですので、きちんと地域の方のご意見を取り入れながら進めていく、これは当然のこととして考えてあります。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"それを受けた形で、むしろいろいろな方、専門的な方々がオブザーバーになるぐらいの形ではなかろうか。やはり地域の都市再生ですから、そういう思いをしっかりと受けとめた形で進めていただきたいなというふうに要望したいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一番最後のところに出ている「計画に記載された備蓄倉庫に係る課税の特例措置」とか、ここら辺はどういう対応をするのか。その辺の手続き、課税特例というのは区の部分なのか、それとも国の分まで含めてなのか、その辺はどうなっているのか尋ねました。","respondent":"古巻防災課長","answer":"課税特例に関しましては、基本的に国税、所得税だったり不動産の所得税であったりと、そういったものになりますので、区の税金ということではございません。","id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"すると、この地域の部分だけは対象になるけれども、それ以外の一般企業は、備蓄に関してはその辺は全然対象外だということなのか尋ねました。","respondent":"古巻防災課長","answer":"備蓄倉庫に係る課税の特別措置ということですので、計画の中に位置づけられた備蓄倉庫については特例措置の対象になるという考え方です。ですから、民間の倉庫であっても、計画上定められた倉庫ということであれば、特例措置の対象になるという考え方です。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この開発予定地区、5)都市再生安全確保計画の活用で、開発予定地区の整備、要するに開発予定地区だけが対象になっていて、それ以外の部分は対象にならないと、そういう捉え方か尋ねました。","respondent":"稲田都市開発課長","answer":"大崎駅周辺地域都市再生緊急整備事業の６０ha、この地域の中において、このような防災の計画を立てて位置づけていくもので、この倉庫等にかかる税金等は支援を受けることができるという考え方となっております。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その下に矢印で３本に、この辺の具体的なイメージができないので、そこも教えていただきたいです。5)の１個目の丸に書いてあるのですけれども、「整備がほぼ完了し」というのはどういう捉え方をしているのか伺いたいのですけれども、お願いします。","respondent":"古巻防災課長、稲田都市開発課長","answer":"それはこれから具体的には検討していきますけれども、避難誘導の部分で安全に避難ができるような経路を確保するとか、そういったところ。それから備蓄で若干対応する必要が出たときに… Ａ３横の資料の5)都市再生安全確保計画の活用の最初の丸のところの「開発予定地区の整備がほぼ完了し」の内容ですが、この６０ha。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたら、今回のこの大崎駅周辺地域都市再生緊急整備協議会というのは、帰宅困難者対策をつくるための協議会なのですか。それで、この計画、都市再生安全確保計画の策定が求められているというのは、国からのことなのか、そこもちょっと伺っていきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"今日出された大崎駅周辺地域都市再生緊急整備協議会というのは、帰宅困難者対策を進める大もとの協議会ということになるということなのですか。それとは別に、都市再生安全確保計画というのが大もとにある、そういう感じなのか尋ねました。","respondent":"古巻防災課長","answer":"今日ご説明いたしました都市再生安全確保計画を策定するために設立をするものですので、こういったものについての安全確保、防災上の安全を確保していく計画を策定するための協議会です。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは６０haの外側に、今西品川一丁目の国際自動車の跡につくっていますよね。あれを含んでいないのですけれども、今後でき上がったときに協議会の中に入らないとおかしくなると思うのだけれども、それはどう考えるのか尋ねました。","respondent":"古巻防災課長、稲田都市開発課長","answer":"現状では、まずは決められたエリアの中の計画ということで進めていく形になろうかと思います。先々はエリアとして含むことになるかとも思いますので、そこはちょっと十分調整をしながら進めていきたいと考えています。 大井町、大崎、五反田という都市軸の中に位置する地域なのですね。今後どう取り扱うかはまた別としましても、一つのそういうまちの構成の中においては少し考えていく必要があるところかなとは思っております。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それを前提に計画していかないと、後でできた計画が変わってしまうということをある程度想定していかないと、今後の計画が全然狂うのではないかなと思うのですけれどもとの意見を述べました。","respondent":"稲田都市開発課長","answer":"いろいろな議題をもとに年１回の総会、それから委員会がありまして、委員会を年４回等々やってきております。西品川地区もこのまち運営協議会という中には加盟していますので、そういうものも含めて防災関係におきましては検討していくです。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その課題はわかりました。ですから、今の６０haの中だけで考えると、そういう考えなのですが。","respondent":"稲田都市開発課長","answer":"ここにオブザーバーとしてこの資料の右側、エリアマネジメントというのが入っております。今後防災のほうで考えている協議会とも連携をとりながら、連携しながら、やっていきたいと思います。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"そこも含めた形でしていかないといけないのではないですかという意見とかが言えて、では品川区独自で何かやっていこうという場合できるのですか。財政措置も考えた中で、現実的にどこまでできるものなのか尋ねました。","respondent":"藤田都市環境部長","answer":"実際に大崎駅周辺の都市再生緊急整備地域、それを今すぐに西品川のエリアも含めて変更していこうというのはなかなか難しいかなと思ってあります。","id":"exchange-051"}]},{"id":"topic-06","title":"第３３回品川区防災フェア","agenda":"第３３回品川区防災フェア","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ちなみに、来場者というのはどのぐらいあるのでしょうか。たくさんの方に知ってほしいし、来てほしいという思いがあるのですけれども、来場者の規模はどのぐらいの目標を持ってされているのか尋ねました。","respondent":"古巻防災課長","answer":"来場者ですけれども、昨年度の数は１,１００名ということで、１,０００名程度の方にご来場いただいています。会場をよりわかりやすいといいましょうか、さらに周知を進めまして、昨年度以上来場していただけるようにしていきたいというふうに考えております。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"１,０００名ちょっと、もうちょっと来てほしいですね。３,０００人、４,０００人の規模でやれたらいいなというふうに思って、広めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-07","title":"所管事務調査を一括して議題に供します。 今期の所管事務調査、震災対策につきましては、昨年発生した熊本地震の対応状況等の行政視察…","agenda":"所管事務調査を一括して議題に供します。 今期の所管事務調査、震災対策につきましては、昨年発生した熊本地震の対応状況等の行政視察…","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"この案が出てきて、我々議会側に出てくるのはいつ頃の目途で考えていたらいいですか。一番最後のページの修正のスケジュール案のところで言うとどの辺に出てくるのかというのが１点です。","respondent":"古巻防災課長","answer":"素案の取りまとめが、かつまとめに入っていくと思いますので、その段階で１回素案という形でご報告する流れになろうかというふうに思います。９月末か１０月に入ってからということになるかと思います。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その辺を確認したかったのと、震災によって火災が起きたときの対策というのは、その辺はどこかに入っているのか。火事という観点はどこかに入っているのかというのが見えないので、教えてもらえればと思います。","respondent":"古巻防災課長","answer":"大規模な火災につきましては、現在の計画には特段位置づけが十分ではないのですけれども、大規模な火災につきましても、大規模事故等の中で位置づけをしていく予定で考えております。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"確認","question":"大規模というのは、後でどういうものを含めて大規模事故かなと確認しようと思ったのですけれども、大体意味はわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"今の大規模事故のところで、そうすると、私たちの一般質問のところでこの大規模事故というのは何かというのをお聞きしたのですけれども、改めて今、大規模事故というのは、今の質疑の大火、地震ではないものでの大きな火災被害なんかを想定しているのかを伺いたいと思います。","respondent":"古巻防災課長","answer":"一定取り上げていこうという考え方ですので、また、品川区に対して大きな影響のあるものを取り上げていくというような考え方です。細かな具体的な中身につきましては今後検討していくということで、一般質問の中でもご答弁していますけれども。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"大規模事故というふうに位置づける事故、災害の種類、そういったのは平成２９年度の中で細かく議論されていくということなのか尋ねました。","respondent":"古巻防災課長","answer":"委員ご指摘のとおりで、具体的な中身につきましては計画の修正を検討する中で、項目としてどれを取り上げていくのかという。そういったあたりまでの取捨選択につきましては、来年度具体的に詰めていくという考え方です。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問","question":"航空機災害というのですかね、そういうのは、今の段階では項目は決まってきていないということですか。今の段階である、大規模事故が何かというのをちょっと伺いたいのですけれども。","respondent":"古巻防災課長","answer":"今の段階では、こちらはそれぞれ品川区において必要なもの、それほどでもないものということで取捨選択していくという考え方です。基本的には一般質問の中でも申し上げたとおり、連絡体制の確立のためのそういった洗い出しが主体になっていくかというふうに考えているところです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこをこれから具体的にということなので、ぜひ私たちも議論できるような形で進めていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"古巻防災課長","answer":"大規模事故災害につきましては、何を含めていくのかというのは当然最終的な素案をつくる段階では想定して一定お示しをするというような形になろうかと思いますので、素案をご提出する際に十分説明をさせていただきたいというふうに思います。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"最初にちょっとお伺いしたいのは、そういうものをどういうふうに考えたらいいのだろうと、そこを今どんなふうに捉えているのか。災害の想定外というか、短期間に２度震度７が来るという災害というのを防災計画案の中でどういうふうに捉えているのかというのが一つです。","respondent":"古巻防災課長、鈴木建築課長、曽田災害対策担当部長","answer":"熊本地震の教訓はさまざま考えられるところだと思いますけれども、それに基づいた計画の内容にしていきたいというふうに考えております。 考え方としましては、やはり大きい地震が２度来たものに対する建物の耐震性の向上というのは、基本的には今考えていないと。… そういった、震度７が２回起こるという前提ではなくて、もう１回揺れて危険があるといったことについては具体化していかなければいけないと考えております。","id":"exchange-061"},{"speaker":"塚本委員","kind":"質問","question":"次に、加えるというところで、新たな災害に大規模事故災害と火山災害を加えていくと。どういうものが起こるかといって、例えば火山災害だと品川区においてどういう災害が起こり得るとして考えるものなのか尋ねました。","respondent":"古巻防災課長","answer":"東京都でもそういった観点を主に防災計画をつくっているところです。品川区もそれに倣いまして、基本は降灰の影響ということで表記をしています。","id":"exchange-062"},{"speaker":"塚本委員","kind":"質問","question":"そのときにこういうふうに対応していくのだという予防なり対応なりというのを想定していく考え方がやはり適切なのか。状態みたいなもの、どういうふうに新たに加える大規模事故災害、火山災害等についての計画を進めていこうと思っているのかをお伺いします。","respondent":"古巻防災課長","answer":"事象によって記述のレベルといいましょうか、具体的にある程度想定ができるものと、もう少し大きな括りでないと想定が難しいものとあると思います。","id":"exchange-063"},{"speaker":"高橋（伸）委員","kind":"質問","question":"熊本地震を踏まえて、先ほどほかの委員からもお話がありましたけれども、車中泊とペット避難の対応の中で、平成２９年度の震災編の中では、第８部の帰宅困難者対策に入るのか、第９部の避難者対策に入るのか、その辺の区別というか、そこがわからないので説明を求めました。","respondent":"古巻防災課長","answer":"今委員がご質問になった車中泊であったりペット対策だったりというところにつきましては、主には避難者対策という中で対応していくものかなというふうに考えております。","id":"exchange-064"},{"speaker":"高橋（伸）委員","kind":"意見","question":"特に車中泊は、実際品川区内で発災したときに車中泊は当然相当多くの方が来られると思うのですけれども、その辺の車中泊のことはどういうふうに今現在対策を立てているのか、説明を求めました。","respondent":"古巻防災課長","answer":"いわゆる避難所以外への避難、車中であったりとか、まずきちんと計画の中に位置づける必要があるのかなというふうに考えております。ちょっとそこはまた来年度の修正の検討の中ではありますけれども、それに応じた計画を具体的にしていくというような形になろうかと思います。","id":"exchange-065"},{"speaker":"高橋（伸）委員","kind":"意見","question":"逆に家屋が三十数年経っているところは、間違いなくとは言いませんけれども、家屋解体が発生すると思うのですね。家屋の解体等は、品川建築防災協会とかいろいろ含めて、今現在どういうお話をされているのか説明を求めました。","respondent":"古巻防災課長","answer":"住宅の撤去に関しまして遅れがあったという熊本の教訓につきましては、区としてもそうした対応が必要だということは認識しています。","id":"exchange-066"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最後に、海岸のほうなのですけれども、液状化というのも想定できるかと思うのですが、そこの液状化のことに関しても教えてほしいと求めました。","respondent":"古巻防災課長","answer":"液状化につきましては、対応については、液状化の現象が起こった際の対策というのを当然含んで計画に取り込んでいく必要があろうかと思います。当然新しい修正をする計画においても、液状化というのは想定をした上で計画を立てていくということが必要になろうかと思います。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"それらについてどう考えられるのか。それから２日目、３日目という形で運営に対してもいろいろな変化が出てくる可能性はあるので、いかがか尋ねました。","respondent":"古巻防災課長","answer":"あまり計画の中では触れていないようにも思いますので、工夫をするなり、どういう形にするかは今後の検討の中で決めていきたいというふうに思います。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"これは概要版とかをつくるのですよね。全体をしっかりつくっていただくのと、概要版というのを何かつくって区民の方に知らしめるとか、そういう方法を同時に考えていただけないか尋ねました。","respondent":"古巻防災課長、松代防災まちづくり部長","answer":"周知という意味で、本冊全部を通読して理解をしてくださいということはかなり無理があることだと思いますので、ポイントを押さえた概要版といったものも用意して、十分に周知が図れるようにしていきたいと思います。 区民の皆様の目線から見たときに、本計画の開始をした後、防災ハンドブックの改正を行います。必ず自分たちがしなければいけないのは何かというのをお知らせするような計画にしていく必要があると、このように思っているところです。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/132633?Template=document&Id=4196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":46959,"voices":190}},{"id":"h29-20170228-9","meetingId":"h29-cm02","date":"2017年2月28日","dateIso":"2017-02-28","committee":"文教委員会","time":"午前１０時００分～午後 ３時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件整理しています。","topics":[{"id":"topic-01","title":"（仮称）品川区子ども・若者計画","agenda":"（仮称）品川区子ども・若者計画","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"今、これを拝見したのですけれど、このような会議が必要なのでしょうか。あえて積極的な意味はこういうことがあるから、こういう計画で、こういう行動をしたいという、課長からの何かご説明がいただきたいのです。","respondent":"高山子ども育成課長","answer":"若者の育成支援を掲げます中心的な会議体として区長の附属機関として設置されてきたものですので、このような趣旨です。子ども・若者支援に資する施策は着実に遂行してきたところではありますが、この計画については策定してまいりたいと、そのような趣旨です。","id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問","question":"着実に行われてきたと思っているのですけれど、さらにその上で、子ども・若者計画というのは何をやるのでしょうか。その目的がちょっとよくわからないのですけれど。","respondent":"高山子ども育成課長","answer":"施策としてはこれまでも着実に取り組んできたものを、そのこと自体も大変意義深いことと考えておりますので、当事者が当事者としての意識を持って今後の施策を展開していくというような形で進めてまいりたいと考えております。","id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"あまり東京都が何か言ってきて、それに品川区が振り回されるのも大変なので、消極的な意見もあったということで考えていただいて。質問ではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"既にある５０名の青少年問題協議会の中からの１５名で、それぞれの中から１５名ということでよろしいのかということを教えてほしいと求めました。この分析結果を見て、さまざまここも考慮した上で、これが子ども・若者計画に反映されていくということでよろしいのか尋ねました。","respondent":"高山子ども育成課長","answer":"区民の方にもわかりやすい形で子ども・若者支援の区の姿勢を示していきたいと考えております。あるいは近隣で言えば横浜市などの調査などと比較しながら、品川区の実態について浮き彫りにしていきたいと、このような趣旨で実施するものです。","id":"exchange-004"},{"speaker":"新妻委員","kind":"確認","question":"若者なので３０代ぐらいでしょうか、このアンケートは、その世代ごとに読み取れるのかというところです。そこが具体的に反映できるものがあるのかというところをもう少し確認したいと思います。","respondent":"高山子ども育成課長","answer":"ではどのような活用を考えているかと申しますと、そのような趣旨ですので、大きく中心は３０歳－３９歳までの層を中心とするものです。おおむね３０歳までなのですが、３０歳以降についてはポスト青年期ということで、おおむね４０歳未満までをターゲットに考えているものです。","id":"exchange-005"},{"speaker":"あべ委員","kind":"意見","question":"年齢の中心ターゲットが違うけれども、両方、「子ども」という括りのものなのか。どういうところが重なっているのか、重なっていないのかというところを、まずご説明いただけますかとの意見を述べました。","respondent":"高山子ども育成課長","answer":"総合的な子ども・若者の育成支援の施策という視点で言えば、そういった意味も含めまして、この計画については考えているところです。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"何か、狙いの部分といったらいいのですか。どんな問題意識を持って、新たにこの子ども・若者計画というのをつくろうとしているのかというところをご説明いただけますか。","respondent":"齋藤子ども未来部長","answer":"先ほどから課長からご説明させてもらっていますように、あるいは社会に対する社会保障という点で、いろいろな課題が見えてくる。これまでも次世代育成支援計画というのがあったのですけれども、アプローチとしては結構、似ているのです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"確認","question":"行政が直接エントリーしていくものなのかどうか。その思いといいますか、こういうふうにやっていきたいというような問題意識と言えばいいのか、もう一度確認させていただけますか。","respondent":"高山子ども育成課長","answer":"そういう意味では、委員ご指摘の部分も、ご意見として委員会の場でも頂戴できるのではないかと考えております。ぜひそういった、さまざまな立場の方の意見を踏まえまして、計画として良いものにしていきたいと考えております。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"これで終わりにしたいのですが、ここに教育委員会というのはどのようにかかわっていくのか、またかかわっていかないのか。教育委員会とのかかわりが、この１枚の中ではちょっと見えにくいのですけれども、どのような感じなのか尋ねました。","respondent":"齋藤子ども未来部長、本城教育次長","answer":"今回は子ども・若者計画のご説明でしたのですが、今年度からのご案内のとき、来年度にも事業展開しようと考えております。町内の中でしっかりと議論することが大切だと考えていますので、その輪の中で関連させながら… ここで言う若者の世代に通じる面というものは、ある意味では義務教育学校の段階から生じるものもあると思われますので、そういう意味で連携をいろんな形でとりながら進めていきたいとは考えております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"今回の子ども・若者計画では次世代育成支援計画のほうを包括的にやっていくというところ、なぜそうなったのか伺いたいと思います。その上位計画といいましょうか、国や都がやっている子ども・若者育成支援推進大綱、東京都子供・若者計画という概要を説明ほしいと求めました。","respondent":"高山子ども育成課長","answer":"それから２つ目の方針としましては、社会的自立に困難を有する子ども・若者やその家族への支援。そういった３つの基本方針に基づいて、より詳細に引き継いだ上で、そのような計画と認識しております。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今回の子ども・若者計画も、この子どもの権利条約に基づいたものにしていくのかどうかということをお伺いしたいと思います。議事録等はどうなっているのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"それから子供・若者育成支援推進大綱、こういった部分の趣旨については十分に酌んでまいりたいと考えております。公開の場での審議というのは用意されているものですので、委員会審議につきましては別途、検討させていただきたいと考えます。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"インターネットなどでも、意見の公募などしたらいかがでしょうかということと、パブリックコメントは期間はどのぐらいされるのでしょうか。十分な意見を言える期間を保証していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"そういった方々には意見を申し述べていただくということで、会議に参画していただくということを予定しております。要綱に定めます１４日以上ということを原則として、今後、委員会の委員の方々と意見交換しながら定めてまいりたいと考えております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのお考えはいかがかということと、先ほど高校中退の方も支援できるようにというお話がありましたけれども、大学中退もあると思うのです。大学を中退した方の支援もどうなっていくのか、検討されるのか、伺いたいと思います。","respondent":"高山子ども育成課長","answer":"計画において大きく方向性を示した上で、個別の施策については拡充していくという方向で進めてまいりたいと考えております。意見交換の中でそういったものが出てくれば、計画の中で反映すべきものは反映しつつ、計画の中身としては充実させてまいりたいと考えています。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"計画を立てていくということが、今、求められているのだと思っています。ここは要望です。","respondent":"高山子ども育成課長","answer":"３月、ひと月かけまして、調査結果について分析を図ってまいりたいと思います。早ければ４月などということで、何がしかの、委員会の場においてご報告申し上げたいと考えております。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望です。勉強不足なのですけれど、平仮名「ども」でやるのか尋ねました。","respondent":"高山子ども育成課長","answer":"品川区においては、「ども」は、法律「子ども・若者育成支援推進法」のほうを用いるような形で、平仮名表記を考えているところです。都においてこのような漢字表記を採用した経緯については把握しておりません。","id":"exchange-015"},{"speaker":"あくつ委員長","kind":"質問","question":"私からも１点だけ伺います。そういったものが明記されていくような種類のものなのかどうか、そういう種類のものなのかどうか、そこら辺についてお伺いしたいのですけれども。","respondent":"高山子ども育成課長","answer":"中身につきましては、品川区ならではの実態を把握したいという趣旨で実施しておるものです。現在のところは、子ども・若者計画策定に当たって必要であるような基礎的な情報収集というような形で、今回実施させていただいたものです。","id":"exchange-016"}]},{"id":"topic-02","title":"保育園の民営化と施設の改築計画","agenda":"保育園の民営化と施設の改築計画","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"児童センターのところをお伺いしたいと思います。ここで行われているイベント等もあると思うのですけれども、その間どうされるのかというところを確認させてください。","respondent":"高山子ども育成課長","answer":"児童センターの閉館中の取り扱いということですが、品川区内には２５の児童センターがあります。館で行っている事業につきましては、代替施設としまして、近隣の児童センターのご利用について丁寧にご案内してまいりたいと考えております。","id":"exchange-017"},{"speaker":"新妻委員","kind":"意見","question":"ということは、今ある児童センターにご案内ということで、特にそれぞれの児童センターに対しての代替え地はつくらないというお考えということですねとの意見を述べました。","respondent":"高山子ども育成課長","answer":"閉館中の児童センターを、別途、施設を確保して、そこに機能をそのまま移すということではなく、既存の児童センターの近隣館をご案内するという形での運営を、現在のところは考えているところです。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"丁寧なご説明をしっかりとしてほしいと求めました。そしてそのほかの児童センターも、こういうことで人が増えるということもしっかりと周知してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"確認","question":"一体的に民営化とか、そういうことではないですか。ちょっと確認させてください。","respondent":"高山子ども育成課長","answer":"南ゆたか保育園と一本橋保育園はいずれも既に委託館ということで、職員がいない施設です。その運営委託の処遇につきましては今後検討するということになりますが、委託の手法・内容についての検討ということになろうかと考えています。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"改築の費用なのですけれども、この保育園は改築の段階で区立園であるということは、改築の費用は全て品川区として支出するということなのでしょうか。いろいろ国からの補助なども出ると聞いておりますけれども、そういったメリットというのは今回の改築では特にないということか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"ご質問の件ですけれども、区の施設ですので、費用については区のほうで負担いたします。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"かつ、今回の整備についても区で全部出すのだということですと、民営化による金銭的なメリットというのは特にないということになりますでしょうか。これは、区立のままで建て替えをやってそのまま運営しても、あまり変わらないのではないかと思うのですが、その辺はどうなのか尋ねました。","respondent":"齋藤子ども未来部長","answer":"当初の方針では公設民営を前提で考えておりましたし、コスト面のことで補助金のこととか、その点は引き取らせていただいて検討させていただきたいと考えています。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"今のご説明では非常にわかりにくい点があったのですけれども、まだこれは実施までに流動的な部分もかなりあるということなのでしょうか。今のお話をもう少し解説していただけますか。","respondent":"齋藤子ども未来部長","answer":"それで、何がいいかはまたその時点で、まだちょっと間がありますので、考えさせてくださいということです。今ここの場でお約束をさせてもらうのは厳しいということで、よろしいでしょうか。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"公立でも多分、公設でもいいのではないかと思っていますので、何でここで民営化にするのか。お金の差がないのであれば、何か大きな理由というのをもう一度説明していただければと思うのですけれど、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"民営化の件ですが、委員ご指摘のとおり、完全に民営化すれば、運営費に関しても施設整備についても財政面が相当変わります。１年１園程度、５園あたりを、１つ目のステップとして民設民営に移行する計画であります。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"ただ、お金のメリットがないのだったら何で民営化するのという単純な質問です。もう一度ご答弁ほしいと求めました。","respondent":"佐藤保育課長","answer":"費用面でのメリットは我々でも認識しているところなのですけれども、段階を踏まえて費用面のメリットをとりにいくといいますか、そういう姿勢でいくです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"これは間をあけるのは何か理由があるのかどうかというところをお聞きしたいのと、もう少し詳しくお聞きしたいのと、お伺いしたいと思います。すべきではないと思いますけれども、伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"まだ民営化予定の園はなく、民営化の基本方針の（１）の3)、なるべく場所として離れたところのほうが妥当ではないかという点も考慮した次第です。南ゆたか保育園につきましては、今回のところで民営化の予定はございません。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"こういったところで、なぜ選ばれたのか伺いたいと思いますし、やはり距離の問題が結構あると思うのです。その点も伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"以前の文教委員会でもご説明しておりますが、同じ敷地内に園をもう一つ建てるというのは不可能ですので、代替地をどこかに探さなければならない。ただ、では、ほかの施設を持っていけるかというと、なかなかその近隣だと厳しいものがあるとは思います。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"ほかの施設は難しいというのは、ゆたか保育園なども近くにあると思うのですけれど、ゆたか保育園ではなく一本橋保育園だった理由というのは、どういった理由か尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"こちらは直営館です。その辺と、あと年間の利用者数などもあり、ゆたか児童センターの場合、倍以上の利用者等がございました関係で、今回は一本橋保育園を選んだ次第です。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"そうしますと、今、南ゆたか保育園も一本橋保育園も児童センターが併設されておりますけれども、現在の、ほかに比べてそこはどうなのでしょうか。南ゆたか保育園と一本橋保育園、あとゆたか保育園も先ほどありましたので、平均と比べて多いのか少ないのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"資料の３．改築施設のところに、児童センターの年間入館数というのがありますけれども、こちらで比較していただくと、数的には約半分以下です。ゆたか児童センターの利用者数に比べて、南ゆたか児童センターおよび一本橋児童センターの利用者数はほぼ半分以下です。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"南ゆたか保育園と一本橋保育園を合わせて４万６,０００名の方が年間利用しているというところで、賄い切れるのでしょうか、伺いたいと思います。平成３３年度に間をあけるというところは、ほかの活用などというのは考えていらっしゃるのか、どうなるのか伺いたいと思います。","respondent":"高山子ども育成課長、吉田保育施設調整担当課長","answer":"品川区内には２５の児童センターがあるということで、他の区と比較しましても、児童センターの数としては大変充実している状況にあります。来館者の状況を見ながら、その都度、進め方については、年間計画を立てる中で… 平成３３年度の空白につきましては、この間は、特に建て替えのために使うということはございません。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"伺いたいと思います。２年間、ぜひ考えていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長、齋藤子ども未来部長、高山子ども育成課長","answer":"その間に、建て替えを含めて２年ずつ、かつそれぞれ２園ありますものですから、２園あって４年かかる。間が１年あいてしまいます。例えば小学校であれば財調で６億円、中学校であれば１１億円と見込まれているのですが、ありません。築５０年以上の園が６園ありますし… 繰り返しの答弁となりますが、児童センターの代替施設の確保については、現状、検討しておりません。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは、さっきから何回も、ほかの方も質問しているので、強く求めたいと思います。基本的なところなので、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"児童センターの代替地というのは、我々も中で大変検討したのです。プラス、今度、新しい事業者の方も積極的に保護者説明会にも出て、保育の方針を示してくれていますので、保護者も安心してくれています。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ひろまち保育園のこの間の経過を見ていたら、区立保育園の保育内容・水準をどう維持していけるのかというきちんとした方向性がないではないですか。意見だけ言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"これは平成３１年度から平成３５年度までの５年間、子ども未来部としてなのか、一括借り切りにという形になっているのでしょうか。その２点をまず説明を求めました。","respondent":"齋藤子ども未来部長","answer":"やらなければいけない保育園というのは考えておりますし、おおむねのスケジュールも予定はあるのですが、仮移転場所の確保に難渋しております。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう一度ご答弁いただきたいのと、その委託というのは２年間で切れて、職場がなくなる状態になるのでしょうか。そこも確認させてください。","respondent":"齋藤子ども未来部長","answer":"施設のスペースの限界もありますので、私どもとしてはご理解をいただきたいということをお願いしたいと考えています。雇用の問題については重要なことですので、雇止めのようなことはないような形で、きちんと対応していくつもりでおります。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-03","title":"平塚シルバーセンター跡オアシスルームの整備等","agenda":"平塚シルバーセンター跡オアシスルームの整備等","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"運営上、両者が何か交流できるようにとか、何かそういうことというのも考えられているのでしょうか。商店街に近いので地域の交流ですとか、そういったことも運営面で配慮していただければと思うのですが、今のところお考えがあれば説明を求めました。","respondent":"佐藤保育課長","answer":"委員ご指摘の、高齢者と子育て世代との交流の場ですが、今所管の高齢者部門ともそういう話はしておりまして、地域のコミュニティーの活性化にもつながりますので、定期的に行っていきたいと考えております。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"裏面の２階のポップンルームのところで、だれでもトイレで、一緒に使ってもらうという考え方なのでしょうか。オアシスルームのほうは子ども専用のトイレがあるのですけれど、ポップンルームのほうはどうなのかと思って伺いたいと思います。","respondent":"佐藤保育課長","answer":"こちらに関しても、１日当たりの利用者は大体１５名程度です。そちらに関しては、サクセスアカデミーという、品川区内でも保育園の運営もしておる事業者が行っております。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"それで、保健センターから今回、こちらのほうに移転するということで、保健センターのあいた部分というのはどうしていくのでしょうか。もうそれは、何か利用の方向性というのは決定しているのでしょうか、伺いたいと思います。","respondent":"佐藤保育課長","answer":"荏原保健センター内にあるポップンルームの件ですが、現時点では、オアシスルームの定員をさらに増やして、受け入れを拡充したいと考えております。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"その辺の考え方というのはどういうことなのか、ちょっと教えてください。そうですよね。","respondent":"佐藤保育課長","answer":"「その他」で説明しようと思っていたのですけれど、区の保育士で、実際にオアシスルームで働くことを希望をする方がなかなか少ないです。継続して１人の子どもの成長を見たいという希望が高いので、平成２９年４月から民間事業者に委託する予定で、検討しております。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"伺ってよかったと思うのが、よい保育ができると思っていたのですが、平成２９年４月から委託になってしまうのですか。直営がしっかりと、１カ所でも残っていることが大事だということを感じていますが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"特に所管の保育課のほうでも、保護者の方からのご要望の連絡はありますから、そういったもので把握しているところです。繰り返しになるのですが、その方が今年度で６５歳になるということもありますので、今回は民間委託することになっております。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"すみません。１つ教えていただきたいのですが、そういう確認というのはどのぐらいされているのか尋ねました。","respondent":"有馬学務課長","answer":"個々の児童・生徒がどのぐらいの割合で予防接種をしているかというのは、学校ではつかんでいるかもしれませんけれど、私どもについては、報告を常にもらっているという状況にはありませんので、それはつかんではおりません。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問","question":"学校の先生は受けましょうということは話をしていたとしても、強制ではないと思うのですけれども、インフルエンザの予防接種を受けるという方向性の指導というのはどうか尋ねました。","respondent":"有馬学務課長","answer":"基本的には保護者のほうの考え方で受けていただくというような方針になっていると考えているところです。各学校のほうで、保護者に対する奨励は、一応している部分はあるです。","id":"exchange-043"}]},{"id":"topic-04","title":"平成２８年度品川区教育委員会の事務事業の点検および評価","agenda":"平成２８年度品川区教育委員会の事務事業の点検および評価","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"１８ページ、例えば人気のある事業というのはどういうものなのか、それが今後どのような形になっていくかということを教えてほしいと求めました。それから１９ページが、何といったらいいのでしょうか、すごいなと思って見ていたのですけれども。","respondent":"有馬学務課長、熊谷指導課長、村尾教育総合支援センター長","answer":"基本的には、何か合議体のようなものを設けるということはせずに、内部で検討を行ってみました。そういうことを総合的に考えまして判断したのですけれども… 過去におきましても、やはり現段階で平成２９年度は４区のみが互助会事業を継続ということで、今後はそういった時代の流れも鑑みながら。… 保護者に学校を開こうという取り組みだったのですが、地域にも十分開かれた学校づくりということで、特色ある教育活動も進めているというところです。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"いろいろと、品川区の教育の変遷も感じながら伺っておりました。かつ、まだこの先どのような配慮が必要であるかということを、どう考えていらっしゃるか説明を求めました。","respondent":"熊谷指導課長","answer":"７年生からのいわゆる転入になりますけれども、これにつきましては、やはり転入対応を配慮して行っています。後半につきましては、今後の学事制度審議会等で、そういった義務教育学校への編入等については検討されていくところだと考えております。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"教育委員会として生み出しているわけですから、そういった、さらにきめ細かい配慮とご理解が必要なところだと思うのです。どう接続させていくかというところは、それなりにやはり知見を組み合わせていただきたいのですが、お考えを説明を求めました。","respondent":"熊谷指導課長","answer":"今、そういった子どもに対する配慮については検討していますが、やはりそれは学校の教員の支援・配慮が進んでいるからだと思います。どういった配慮が必要か、また支援が必要か、そういうことについても引き続き検討していきたいと考えています。","id":"exchange-046"},{"speaker":"あべ委員","kind":"意見","question":"お子様、９５％がうまくいっても、残り５％がいたら、やはりその子に対する配慮というのは必要だと思うのです。ぜひ、きめ細かく対応してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どう取り入れていらっしゃるのかという、ちょっと中身を幾つか、かいつまんでお伺いしたいと思います。とりあえずそこを伺った後で、後半、ちょっとお伺いしたいと思います。","respondent":"熊谷指導課長","answer":"４年生と５年生の間には明確な差があり、指導方法に対応が必要なことについても、一般の方にもわかりやすく説明できるよう。ただ、そういった前期課程終業式の儀式的行事を重視するというお考えもあろうかと思いますので、それについては検討していきたいと考えています。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３５番と８３番で、子どもの疲労度も含めて部活動のあり方というのが検討されているのかどうか、ちょっとその辺をお伺いしたいと思います。ちょっとこれも代表質問で伺ったのですけれども、課題が改善されるのかどうか、この辺をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"４６番の「就学援助」なのですけれども、これまでも求めておりますけれども、ご検討されているのか伺いたいと思います。１人の方を信頼して、いつでも相談できるような形でやっていくべきではないかと思うのですが、お伺いしたいと思います。","respondent":"熊谷指導課長、有馬学務課長、村尾教育総合支援センター長","answer":"主幹教諭の副校長補佐機能の強化でありますけれども、そもそも主幹教諭の役割、職務は、副校長の補佐です。 内部の検討、それから子どもの未来応援プロジェクトを含めまして、全体としてどうしていくかということで検討しています。 ソーシャルワーカー、またカウンセラー等の派遣について検討は進めておりますので、その動向を注視してまいりたいと考えております。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"９年間ということなので、少し長くというふうなことが区として都のほうに要望できるのかということを、どうお考えになるかということです。それから教室を担当した先生方というか教員についてどうだったかという、そこが、どこかにあったのかもしれませんが、お伺いできればと思います。","respondent":"品川庶務課長、熊谷指導課長、村尾教育総合支援センター長","answer":"今も文化観光課と連携して、いろいろとＰＲをしていくかというところは、うまく連携しながら今現在進めているところです。それから昨今… １点目の統括副校長職ですけれども、全校で、役割として位置づけております。義務教育学校だけではなく小・中学校におきましても… 対応しているということで、その対応の仕方、その辺については課題だと考えております。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ものすごくいいものになっているので、ぜひ、ああいう形で整理していただけるとありがたいと思います。今回の小学校のほうを活かして、ぜひいいところは活かし、そうでないところは改善して中学校の実施につなげてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-05","title":"品川区学事制度審議会（第２回～第５回）の報告","agenda":"品川区学事制度審議会（第２回～第５回）の報告","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"月１回程度、その先はどういったテーマも扱うのかなどという、今後の日程とテーマの関係について教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"それぞれの課題について検討した上で、全体の調整を図りながら、そごのないような形で整理していこうと考えております。ある程度時間をとって議論をしてまいりまして、その後、中間答申に向けて全体の整理をしていければと考えているところです。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"その後、ちょっと密接に、何か学校制度に関して特にかかわっている方々については配慮・工夫をしていただきたいところだと考えています。どんな感じで考えていらっしゃいますか尋ねました。","respondent":"篠田学校計画担当課長","answer":"それが実際に施策として実施されていくということになるのですけれども、答申の中身がどういう形になってくるかというのは、まだ微妙な部分です。かなり大きな変更もあるということになれば、４月からいきなり、なかなかちょっと難しいだろうと考えています。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"これもちょっと確認なのですが、第５回目のアンケートの速報というのは、この間、文教委員会でご説明いただいたアンケートということでしょうか。ちょっと確認させてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"第５回目で審議会にご報告させていただいたアンケートというのは、区民に対するアンケートということで、１２月に実施したものです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、このアンケートの内容というのは、今後、文教委員会に報告というのはあるのでしょうか。あったとしても、審議会をやっている最中はないということなのでしょうか、伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"かなり誤解を招くような数字もあるというような話も出ていますので、今のところ、単純集計したものを公表する予定はございません。パブリックコメントをかける段階で、今のところ、まだその前の段階でご報告するということは予定はしていないです。","id":"exchange-056"},{"speaker":"のだて委員","kind":"意見","question":"しかるべきところで、この委員会にも報告してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どのような意見が出たのか教えていただきたいのと、選択制との絡みで矛盾があるといったようなご意見があったかどうか、もしあったら聞かせてください。","respondent":"篠田学校計画担当課長","answer":"あまり深い話ではないのですけれども、学区域の中では、やはり義務教育学校を学区域内に持つ子と持たない子がいるということはどうなのか。今の状況がいいのかどうかといったようなことが、学区域の関係では話としていただいたところです。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"問題と感じているところも含めてお尋ねしたので、１回目のところで、児童・生徒の数が増えているのです。１５年間で３,５００人ぐらい増えているのですが、そういうところにおいて意見が出ているのかどうか、その辺も説明を求めました。","respondent":"篠田学校計画担当課長","answer":"逆に社会性がなかなか育まれないのではないかということ、人間関係が固定化してしまうのではないかということが挙げられているところです。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"適正規模だけではなくて適正配置という意味でもご検討していただきたいと思うので、そこのところが１点と、これから報告してくださるのですよね。ぜひ報告してほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"私どもとしましても当然、そういった中で必要に応じて学校の改築ですとか、そういった形での対応は検討しておりますという形ではお答えしています。学校等の改築等を進めていく中で、この後、そういった部分でもさらに検討を進めてまいりたいところです。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教育に対していろいろお考えのある方が地域にもいっぱいいらっしゃるので、ぜひ広い意見を聞いてほしいと求めましたし、先に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-06","title":"行政サービスコーナーの民間委託と新規開設","agenda":"行政サービスコーナーの民間委託と新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１１１平米というのは、真ん中の階段とエレベーター部分を抜いた部分ということでよろしいのでしょうか、伺いたいと思います。目黒のサービスコーナーについても民間委託していくということなのか、伺います。","respondent":"木村品川図書館長","answer":"それから図面ですが、説明不足でした。それから目黒の運用ですけれども、今のところは委託を想定して検討しているというところを聞いております。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"ちょっと細かいところなのですけれど伺いたいと思います。目黒のほうは、委託の方向だというのは、決まってはいないということなのか尋ねました。","respondent":"木村品川図書館長","answer":"網の部分はご案内のとおり、何もないところは入っておりません。まだ方針としては決まってはおりませんが、再任用職員を配置、プラス委託事業者というような執行体制を想定しているという話を聞いております。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"今のところで、目黒のほうも再任用と委託ということなのですけれど、その仕事のやり方というのは、再任用の方は区の職員ですよね。実際に図書の取り次ぎ業務は、どういう方が具体的にどういうふうにされるのかというのを説明を求めました。","respondent":"木村品川図書館長","answer":"その後、あるいは何かもっと確認しながら進めないとうまく進まないような部分に関して、いわゆる判断・審査業務というのが職員に委ねられているです。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"というと、何か判断をしなくてはいけないというときには委託の方はかかわらないで、そこから再任用の方にかわるということですか。この人がどういう傾向で借りているのか、個人情報をきちんと守れるのかどうかという、その辺の歯どめも説明を求めました。","respondent":"木村品川図書館長","answer":"同様の形で厳格に対応してまいりたいと考えていますが、これは社内ですけれども、事前研修を徹底していただく。それから年２回内部監査を実施する。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よくよく注意していただきたいと思うのと、すごく心配を抱いていますので、どこかでまたしっかりと意見を言っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"意見","question":"区民委員会で話があるかもしれないので、もしその場合は言ってほしいと求めました。目黒のほうも何人でやっていくかということと、あと武蔵小山のサービスコーナーを運営委託していないのはどうしてかということが、もしわかればとの意見を述べました。","respondent":"木村品川図書館長","answer":"大変申しわけございません。やはり所管のほうでの対応の部分かと思いますので、そちらのほうはちょっと。","id":"exchange-067"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"３つ目の質問で、緊急対策を求める質問のところで、待機児は減少するとの答弁がありましたけれども、その根拠を伺います。４つ目の、平等の保育を求める質問ですけれども、そして都の指導・検査に同行している回数が何回なのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"４月開設の認証保育所が２園あり、そこに入る方がいらっしゃいますので、待機児童数としましては昨年度に比べて減少すると見込んでおります。平成２８年度は１４件、年１回の巡回指導をいたしますので、その全てに立ち会う予定です。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"独自に２８園、ほかの区ではどの程度、そういった独自検査というのは行っているのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年の開設に向けましては、平成２９年度に、地域ごとの計画に沿って開設する予定です。独自検査につきましては、小規模を含めまして５８園中３３園の検査および立ち会いをしておりますので、少ないということではないと認識しています。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"入れなかった方も保育園が必要なわけですから、しっかりと待機児ゼロにしていく、入りたい方が入れるようにしていくことが必要だと思います。さらなる努力と、その実現に向けて頑張っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、必要な人が入れているというお話があったので、ちょっとそれで確認できればさせていただきたいのですけれど、２つあります。どういったらいいのですか、３歳からは認証保育園に通えないということで、わかっていれば説明を求めました。","respondent":"大澤待機児童対策担当課長","answer":"認証保育園から３歳児で認可保育園に申し込んでも入れなかった方は、１次の時点では３７名いらっしゃいます。今後、２次等で変わってくるかと思いますが、１次の時点ではその数になっています。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問","question":"わかりました。現在、１次の段階ですので、またどちらも確定した数字が今後出てくると思いますので、また改めて教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"意見","question":"３歳で、もう行き場がないのだけど入れなかったと。なぜ本当に緊急対策を、ちょっとそこがわからないので、そこが１点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"では、違う場で申し上げます。どうして１５０人ぐらいしか入れなくて１,１９０人があふれてしまうのかという、どうしてなのかと質問を受けているので、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"今の数字は、あくまでも１次の数字なので、全ての分析は２次が終わって、最後まで待っていただきたいのですけれども、今回、不承諾が多かった一番の原因は、０歳児と１歳児が集中して増加したということと分析しております。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、１,０４４の中に、０歳・１歳児の集中したのを吸収できなかったという捉え方でよろしいのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"新規開設しましても、０歳・１歳の定員というのはやはり限度がありますので、それ以上に０歳と１歳の申し込みが増えたです。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問","question":"最後にしますけれど、０歳と１歳が集中したというのは、今まで、去年などと比べて極端に多かったのでしょうか。はるかに予想を超えていたのかどうか、ちょっとそこの点を説明を求めました。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"申し込みの増加数が１９３人です。増加数の大体７割が申し込みで増えてしまったという状況ですので、かなりの増加分だと分析しています。親子３代住んでいる区民の人と、排除するつもりはもちろんありませんけれども、どうやって頑張らなければいけないか。","id":"exchange-076"},{"speaker":"あべ委員","kind":"確認","question":"本会議場での鈴木真澄議員の質問の中で、児童相談所の移管についての質問がございました。ご答弁にも、その内容等について、あるいは今後の品川区の考え方について確認させてほしいと求めました。","respondent":"高山子ども育成課長","answer":"２２区一括での移管に向けた対応というのが困難であるといった理由から、三区を選定してほしいといったことについてのご提案がありました。開設予定時期が早い区ということで３区、荒川区、江戸川区がモデル的な対応区ということで選定されたところです。","id":"exchange-077"},{"speaker":"あべ委員","kind":"質問","question":"手を挙げたけれども選ばれなかったとか条件に合わなかったということなのか、そもそも品川区としてはちょっと様子見ということだったのか、どういう状況だったのか説明を求めました。","respondent":"高山子ども育成課長","answer":"今回選ばれました３区というのは、具体的な建設予定地が確定しているといった状況もございました。モデル的な部分の対応については一旦お譲りする形で、速やかな開設に向けて進めてまいりたいという、その意向が変わるものではございません。","id":"exchange-078"},{"speaker":"あべ委員","kind":"質問","question":"既に予定地を探してはいるところなのでしょうか。かなりまとまった土地が必要ではないかと思うのですけれども、その可能性というのを区はどのように考えていらっしゃいますか。","respondent":"高山子ども育成課長","answer":"一時保護所と、それから相談所を合わせまして、おおむね２,０００平米ほどの建物が必要になってまいります。敷地としましては１,０００平米を超えるような土地が必要となってまいりますので、鋭意選定中というか、探している状況にあります。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問","question":"では、スピーディーに検討するというお話があったのですけれども、どういう状況なのでしょうか。今の、移管ではない状況の中でどう進めていくのか、ちょっとあまり見えないのですが。","respondent":"高山子ども育成課長","answer":"そういったことで考えますと、３区が全く同じタイミングで移管を進めないことには、施設の活動というのは非常に難しいという状況になります。児童相談所設置地というのが法令上の用語ですが、そして人材の供与、移管という言葉にこだわっているといった形です。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、最終的には、原因というのはまだわかっていないということか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"現時点では、明確にこれが原因だということはわかっておりません。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"最後に意識啓発に努めてまいりますというお話があったので、本当にそこが大事だと思うのですけれども、実際にこういった事例はどうやって全職員の共有の理解になっていくのか、そこのところを説明を求めました。","respondent":"熊谷指導課長","answer":"本区の園長、校長を対象に、この件につきまして説明をいたしました。この新聞記事等を活用しながら、こうした発言が決してないよう、人権教育の充実についても意識啓発を図ったところです。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"確認","question":"園長、校長のところの、資料が届いたり共有された部分が、具体的に各学校や各園で、具体的に話を聞ける場というか交流できる場というのがきちんと確保されているのかどうか、そこを確認させてください。","respondent":"熊谷指導課長","answer":"教職員の人権感覚チェックリストというのがありますので、その資料もつけまして、必ず全員を対象に実施してくださいということを依頼いたしました。","id":"exchange-083"},{"speaker":"あべ委員","kind":"意見","question":"これが起こったからどういう対処をしましたというだけではなくて、やはり多様性について、日ごろから感覚を磨いておくしかないと思うのです。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"質問","question":"あるいは何か研修を１週間受けなければいけないとか、そういったことに関しては、今回の発言などではどうだったのでしょうか。聞き漏らしたのかもしれません。","respondent":"熊谷指導課長","answer":"処分対象にはなりませんが、ただし指導対象ではありますので、毎日２時間ずつ管理職から人権教育に関する指導を継続して行ったところであります。私どもからも指導ということで行ったところであります。","id":"exchange-085"},{"speaker":"あべ委員","kind":"質問","question":"どのような形で１０５％ということになっているのかを教えてください。そういった意味では、半分以上の施設が７０％以上となっているということは、区としてはどのように受けとめていらっしゃるのか尋ねました。","respondent":"佐藤保育課長","answer":"なので、それを今、至急、システム改修をしまして、データの分析を今後進めまして、より有用性が高い事業に再構築したいと考えております。今ご説明したのとかぶってしまうのですけれど、時間帯では４割なので、需要率がどのぐらいあるのか。","id":"exchange-086"},{"speaker":"あべ委員","kind":"意見","question":"今後、システム化するということで、より合理的に使えるようになるのだろうということを期待いたします。断られたという声は、まだまだオアシスルームを増やしてほしいという声とともによく聞きますので、運営を改善してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/154236?Template=document&Id=4908#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":80257,"voices":236}},{"id":"h29-20170228-5","meetingId":"h29-cm02","date":"2017年2月28日","dateIso":"2017-02-28","committee":"総務委員会","time":"午前１０時００分～午前１０時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度都区財政調整","agenda":"平成２９年度都区財政調整","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしますが、交付金の再調整額の、５ページですが、当初算定残額が２１１億円とありました。それに今回、税収増による交付金の増で１１６億円出て、残額も含めて再調整するというのが通常のやり方なのか尋ねました。","respondent":"秋山財政課長","answer":"補正予算で出てきた１１６億円と合わせて、今まであった分と税収増を合わせて、それをまた２３区に配分する。そういうことで、年度の当初というのは税収の見込みでやりますので、最終的な見込みで、今回出てきた分と合わせて配分するという形です。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか教えていただきたいのですが、法人分が約３４２億円減ると見込んでいるのだけれども、５.７％も減ってしまうのかなと。１１月１日以降の契約については固定資産税の免除が発表されたと思うのだけれども、それは２３区でどれぐらい影響があるとお考えなのか。","respondent":"秋山財政課長","answer":"２月２日の都区協議の場で、あえて言うと、特に何か方針の変更であるとかいうようなことはなかったと聞いております。減免割合で、減収の見込みが約６億円ということです。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"６億円というのは、そうなのかなと思いますが、こういうのは我々には全く、区というか地方自治体には、何の相談もなかったではないですか。今の５.７％減るというのは、上回ってくるというのは期待したいなと考えていますが、そこの１点はどうしても聞きたいなと思います。","respondent":"桑村副区長","answer":"東京都のほうも、そういう意味では申し訳なかったということではないのですけれども、丁寧な対応ができなかったということであったようです。特に５５％という、そういうのは十分な協議が必要だろうというのは、多分どこの区長も思われていることだと思います。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なかなかこの５５に手をつけていくのは難しいかもしれないですが、我々が主張しているのは、基本的にはもっと５５以上あるわけではないですか。これは要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"３ページの下の部分、新規算定等の主な項目が幾つか出ているのですけれども、この項目についての品川区の見解、どういうふうに考えているのかというあたりを伺いたいと思います。","respondent":"秋山財政課長","answer":"待機児童解消緊急対策対応経費ということで、保育士の宿舎借り上げ支援事業というのを各区でやっておりますが、入れる合意が成ったと考えています。新規算定では１５項目、算定改善ではプラスマイナスがありますけれども２９項目ということで、ここに載っていったです。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"１歳、２歳という状況を見たときに、とりわけ求められるのではないかと思うのです。待ちの姿勢ではなくて、公設公営が最も適切な対策だと思っているのですけれども、そういう考え方というのは品川区にはないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"緊急課題というところで、もう少しいろいろな状況を勘案して方針化していただきたいと思っているので、考え方を聞いているのです。必要性というのは、都区財政調整の中でどんなふうに見ているのか、それを知りたいと思っています。","respondent":"秋山財政課長","answer":"あくまでも財調算定というのは、これをもってしてその区の政策が、この財調の数値によってどうこうされるというものではありません。そういうふうに認識しているものです。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"品川区が入所児童数の３,４００人と比べてどうかというのは、手厚くそういう方針を持っていただきたいということを、この機会に言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"固定資産税および都市計画税の軽減措置の継続","agenda":"固定資産税および都市計画税の軽減措置の継続","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"これが１点と、２３区全部が出しているような気がしてならなくて、恒久的なものにするという議論は課長会とかそういうところではないのか。東京都は必ず毎年やってくださいのような話なのだけれども、そこら辺の協議というのはあるのかないのか、説明を求めました。","respondent":"黒田税務課長、秋山財政課長","answer":"１点目のご質問にあります、その年の歳入をどのように租税を考えて条例を変えるかというところで、この軽減措置については継続するという旨が公表されているものです。都区協議会の中では分配に関することで、それぞれの調整３税がどのぐらいの見込みがあるかということで、金額の協議というのはしております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそこら辺はニーズがあると思うので、都区協議の中で恒久的なものというのは、どこかのところでやっていただきたいなと思います。それは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858885?Template=document&Id=2070#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":12261,"voices":36}},{"id":"h29-20170301-14","meetingId":"h29-cm03","date":"2017年3月1日","dateIso":"2017-03-01","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ４時３２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区民の皆さんから１０本も請願や陳情が積み上がっているということで、この計画について反対してほしいという思いを、すごく感じているところです。これについて区も同じ認識ですかと質問したのですが、ぜひ同じ立場に立ってほしいという思いがあるのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"国に提出いただきました意見書につきましては、国土交通省が品川区と十分協議をすること、またさまざまな手法で説明会を行う、区民の皆様への理解を、十分周知を行うというところにつきましては、区といたしましても全く同じ意見です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"この間たびたび伺ってきたのですが、ぜひ明らかにしてほしいと繰り返し要望してきたのですけれども、国から回答は来たでしょうか。飛行機の騒音で、視覚障害者の方の通行の安全に、私は大きな支障が出ると思うのですけれども、区は問題だと思うのか、伺います。","respondent":"三ツ橋環境課長","answer":"しかしながら今のところは、まだデータとしていただいておりません。視覚障害者の方というのは、飛行機以外にもさまざまな部分で影響がありますので、そちらはバリアフリーの観点で考えてまいりたいと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区から要望しているというのはそうだと思いますけれど、それは正式な訪問ではないかもしれないですが、接触する機会はたくさんあるわけですよね。区はこの音響式信号機に対する飛行機騒音は、問題だと思わないのかということを伺ったので、もう一度お願いします。","respondent":"中村都市計画課長","answer":"区としては十分国土交通省と密に情報の連携を図りながら、議会に対しましても、情報提供していく義務があると考えております。これは国も同じように、国としての立場で国民に対する周知や説明の義務がありますので、重要だと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"これも引き続き、強く示すよう求めてほしいと求めました。そして、国外機と国内機の安全性というのは同じレベルと考えてよいのか、これも伺います。","respondent":"中村都市計画課長","answer":"それぞれ安全対策、そしてそのレベルは、同等というふうに考えてあります。安全を追求していただくというところでは、同じ基準に基づいて運行していただくことを、また引き続き強く求めていくものです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"やはり新ルートでどれぐらいそうした国外便が増えるか、きちんと把握していく必要があると思いますので、よろしくお願いしたいと思います。大人数の墜落が起きた場合はどうなるのか、難しくなってしまうのではないかと思うのですけれど、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"近年、小型機による事故ですが、定期便とはまた別にプロペラ機とか個人が運用、航行している機体が主なものだと認識しております。これも事故の状況にもよりますので、一概には言えませんが、そのように認識しております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから最大の安全対策というのは、この点でも都心低空飛行の新ルートというのはやるべきでない、そうした立場に立ってほしいと求めました。落下物はゼロにできないということを前提にした対応をすべきだと、私は求めまして、市街地低空を飛ばさないことだと。","respondent":"中村都市計画課長","answer":"今、委員がおっしゃいましたとおり、落下物、事故もそうです、こういったものは起きない、絶対に起こさないということが必要だと考えています。区もそれを推測することは、今、できないと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、確率がいかに低かろうが、やはりこれは許すべきでない計画だと私は思います。私が伺ったのは、あり得ませんよねということを伺ったので、もう一度伺いたいと思います。","respondent":"中村都市計画課長","answer":"区としては、落下物ゼロ、事故ゼロに向けて、国に対して求めていくというのが、とるべき姿勢ですので、引き続き国には求めてまいります。あるいは成田空港が２１件ある中で、やはり０件を目標に国に対策を求めていくという、そういった姿勢です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのですけれども、区は主張しているのですか、この例を引き合いに出したということは。それを伺います。","respondent":"中村都市計画課長","answer":"騒音、こういったものに課題があるので、それについて説明を十分に求めていくです。国としてはさまざま説明はいただいておりますけれども、それは他の空港の状況で、国としては提案していくというふうに聞いてあります。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問は、別にこの上３００メートルを飛んでいるということではないということで、よろしいのですか。ホームページにも出ていますが、３７ページによると改めて、ほかにどのようなものがあるでしょうか」という質問に対する国の回答が載っております。","respondent":"中村都市計画課長","answer":"品川区のこと、品川区民のことだけ考えて、国に対して要望していかなければいけないと考えております。実際に品川区の上空を通るという案を受けて、それに対する確実な安全性といったものを求めていく姿勢に、変わりはございません。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"区みずからがおっしゃっていたわけですから、強く求められていると思いますので、そのことを区にも強く求めたいと思います。財産を守るためにやっているわけですから、ここはむしろ把握していただきたいと、強く申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"従来型の説明会もぜひ並行してやってほしいということは、繰り返し求めてきていると思いますが、どのようにお考えでしょうか。役所の中に常設コーナーをつくるぐらいのことはあってもいいのではないかと思いますけれども、それについては、区の考え方としていかがか尋ねました。","respondent":"中村都市計画課長","answer":"こちらも４月以降という情報がつい先日来まして、対応時間ですとか、これも確認していきたいと考えています。そういった説明会、あるいは今までもお願いしてきた教室型の説明会、引き続き国に強く要望してまいりたいと考えています。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"形としては要望ということになるのかもしれないですけれども、この経路自体、別にこちらからお願いして飛ばしてもらうわけではないですよね。国交省と交渉なり、意見交換をすべきではないかと感じておりますが、そこのところはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"この教室型の説明会にしても、やりたいのですけれどどうですかと、そういった姿勢であるべきなのはごもっともだと。やはりそうすることが当然ではないですかという認識を国に対して持っていただく、これもまた強く、続けて求めてまいりたいと考えております。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"被害を最小にするにはどうしたらいいかということで、足下げのために一旦海のほうに出るとか、そういうことをやっていたわけですよね。ということは、もう何度も繰り返してきたので、意見にとどめますけれども、ぜひそこを考えて、品川区としての姿勢を固めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"ことし１月３１日に、羽田空港は２０２０年には都心上空を飛ぶことが決定と、これについてどのようなご見解をお持ちなのか。まだ決定はしていないはずですから、これは区としてもただしていったほうがよいのかなと考えておりますけれども、その点いかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、その放送の内容についても、誤ったところがあるかもしれません。認識しておりますので、そういったものをただすというのは、現在のところ考えてございません。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"特にＮＨＫの番組ですから、区としての見解を、国に伝えるなりしていただきたいと考えております。平成２８年７月、国土交通省に対してただしていっていただきたいのですけれども、その点どのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"今回の説明会におけるパネル、あるいは案として国が出したものについて、国としてこういう案を出したというのを掲示しています。羽田空港の中の４本の滑走路もいろいろな使い方を検討して、シミュレーション等の検討の中では、その実施に向けてはまだ。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"飛行機がテロ等によって墜落した場合、そのシミュレーションというか被害想定というのは、国はちゃんと考えているのでしょうか。国はそこをどう行っているのか、区としてどのように把握しているのか、お知らせください。","respondent":"中村都市計画課長","answer":"テロへの対応ですけれども、落ちた場合にどうするかというのは、補償の仕組みとして説明がなされております。しっかりとテロの対応というか予防についてやっていくというような説明を受けておりますけれども、対応については特に示されておりません。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"予防はぜひともやっていただきたいですけれども、いくら予防したとしても、最悪なことにそうした事故が発生してしまう可能性はあると考えられます。しかも大型航空機ですから、そうしたことをしっかりと区としても求めていっていただきたいのですけれど、その点のご見解はいかがか尋ねました。","respondent":"中村都市計画課長","answer":"広範囲にわたる危機管理に対する考え方が必要だと思いますので、これは委員がおっしゃいましたとおり、国に強く求めてまいります。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"『世界の都市総合力ランキング２０１６』という書籍も出版されており、そのあたりはしっかりと国は理解しているのでしょうか。そうした確認もとっていただきたいのですが、ご見解をお願いします。","respondent":"中村都市計画課長","answer":"さまざまありますけれども、将来にわたって実際に確実なデータというのはなかなか、把握するのは難しいというのが国の見解だということです。これは飛ぶ前も、飛んだ後も、区としては求めてまいります。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"交通アクセスと、ぜひとも国に対してもそうしたことをお伝えいただきたいと考えておりますが、いかがでしょうか。改めて国の見解をぜひ知りたいですけれども、区としてもそうしたことを伝えていただきたいのですけれど、ご見解はいかがか尋ねました。","respondent":"中村都市計画課長","answer":"先ほどの私の答弁が、ちょっとわかりにくくて申し訳ございません。こういったものにつきまして、国に対してしっかりと把握していただくよう、申し入れを行ってまいります。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"ですから、これは千葉県成田市荒海地区とは大きな違いであって、非常に危険性が高い。区としましては、国に対して出したほうがいいと私は考えているのですけれども、その点について区はどうお考えか尋ねました。","respondent":"中村都市計画課長","answer":"国が示す具体的な方策を検討していかなければいけないと考えておりまして、まだ国から十分な考え方が、検討していく必要があると考えております。現時点においては、まだこの訴訟リスクをとって、区として反対するという段階ではないと考えております。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"現在の技術では到底防ぎようがないということは明らかですから、起きてからでは遅いですから、いかがでしょうか。国に対して中止の意見を出せない、大きな理由というのはあるのか尋ねました。","respondent":"中村都市計画課長","answer":"その一つをとってそれに基づいて反対するということは考えておりませんけれども、まだ国が具体的な案を示していない以上、まだ判断をする段階にはないと考えています。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり中止というのが一番いいのですから、ぜひとも中止のご意見を国に対して表明していっていただきたいと考えております。わざわざ陸地を通る必要はないのではないかと思うのですけれど、その点いかがお考えか尋ねました。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"７時から１１時半と、１５時から１９時ということで今、提示されているところです。ただ、そんな中でも日中の影響が少ないところというのが、国としての考えのようです。 海ほたるに設置している目印、航空灯台の明るさを１０倍にして、工夫しますです。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"では、方策としては有効だというお考えか尋ねました。","respondent":"三ツ橋環境課長","answer":"こちらにつきましては、明るさを１０倍にするものでございまして、目印を視認できる可能性が向上するということで、この部分につきましては、対策は効果があると考えております。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"これは、品川区の今、問題になっている騒音とか落下物の危険性が減るという、直接の対策にはなるのか尋ねました。","respondent":"三ツ橋環境課長","answer":"こちらは、北風時ですけれども、明るさを１０倍にするという部分ですので、品川区につきましては、騒音や高度の部分とはまた別の考え方と考えています。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"増やしていくのではなく、減らしていくべきだと思っているのですけれども、区のお考えを伺いたいと思います。ゼロにするよう求めていくと言っておりましたけれども、どういった方がやるのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"そういった意味で、障害者の方々の意見ですとか、あるいは団体のご意見を聞いたりして、そしてバリアフリーの観点で進めていきたいと考えています。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり音を減らしていくべきだという考えをお持ちなのかということもお聞きしたので、そこもぜひご答弁ほしいと求めました。資格のない人がやっていくという状況で、本当にチェックができるのかなと懸念を持っておりますけれども、区のお考えを伺いたいと思います。","respondent":"中村都市計画課長","answer":"これからも将来的に導入も予定されているということですので、区といたしましてもそういった国や航空会社の取り組みに期待をするものです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても、実現できるまで求めていってほしいと求めましたけれども、改めて意見を伺えればと思います。なぜ２,４００万人達成できたのか、国交省から聞いていたら伺いたいと思います。","respondent":"中村都市計画課長","answer":"説明会の回数ですけれども、品川区で１回行いましたけれども、申し入れを行ってまいります。申し訳ございません。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで２,０００万人目標だったのが、この２,０００万人というのは何だったのか、いかがでしょうか。求めたことはあるのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"国が説明している今回のルート案の中では、こういったものが説明されておりますけれども、まず今回のルート案の中で提示したです。守られないか、これは次の段階としまして国との調整や検討、交渉していくというような内容だと認識しております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"そして大気汚染についても伺いたいと思うのですけれど、ＰＭ２.５については、基準をオーバーしていると。国交省の説明のとおり１５０分の１と区は説明していますけれども、区民に被害がないと考えているのか、伺いたいと思います。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"現段階におきましては国に対して必要な情報を求めていく段階と考えておりますので、現時点において反対を求めていく考えは、今のところございません。大気汚染につきましては、やはり航空機騒音だけでなく、いろいろな道路の関係、交通手段の関係、またさまざまな原因が考えられます。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"シミュレーションするなど、区民への影響を明らかにしていくべきだと思いますけれども、いかがでしょうか。ＰＭ２.５より小さいナノ粒子が排出されているということも、そしてこのナノ粒子についても基準があるのか、伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"国に対してどのようなシミュレーションができるのか、などは、また調整をとってまいりたいと考えています。ＰＭ２.５自身もまだまだ検討、また測定ができるのか、求めてまいりたいと思います。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった中でさらに飛行機が飛んでくるということになりますと、やはり区民への被害があると思うのですけれど、区のお考えを伺いたいと思います。国に対して求めていくということですので、求めていってほしいと求めましたし、区民への影響を明らかにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひその影響をしっかりと明らかにしていくことが必要だと思います。影響を明らかにしてほしいという声もありますし、撤回を求めてほしいということですので、区がまだ説明段階なので求めないということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"さらに、そのうちどれくらいが羽田空港から来ているのかということに関しては把握していないとのご答弁でした。具体的な区内への影響もつかまずに国の方針に従っていくということになると思うのですけれども、区はこれでいいのでしょうか、伺います。","respondent":"中村都市計画課長","answer":"そしてその時間当たりの便数、現時点におきましてはその国が示した案について、それを品川区としてその話を受けているというような形です。将来の変更等については、その検討の中には事案としては入っていないです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"そうした時に、区はどのように対応するつもりなのでしょうか。私はもう明白だと思うのですけれども、区はどのように対応するように考えていらっしゃるのか伺います。","respondent":"中村都市計画課長","answer":"国の説明の中では、新たな滑走路の増設とかいったものが今後の課題として取り上げられているというところにとどまってあります。区といたしましては、この飛行経路案がまた将来にわたって変更するというような時には、その都度国と協議を進めていくべきだと考えています。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"そこは実際今回協議なるものが行われているという認識でいいのかというのをまずお伺いするのと、それと将来その協議というのはどのような協議なのか。その区の意見に対して、国がその賛否の意見を踏まえて決定するというような協議になるのか、そこら辺を具体的にお伺いします。","respondent":"中村都市計画課長","answer":"これもお互いに議論、あるいはそれぞれの要望を伝えたり、また情報共有を行ったりするといったものを協議と認識をしております。実際にその変更案に対する国としてどういった考え方があるのか、また環境影響に対して再度どういった対応がとられるのかといったものを。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"この冊子の２６ページ、新聞・雑誌というのもあるのですけれども、これは具体的には何なのか伺います。この新聞・雑誌とは何なのか、伺います。","respondent":"中村都市計画課長","answer":"この新聞・雑誌ですけれども、この資料２４ページにもそういった種類について列挙されておりますが、ホームページ、ニュースレター、新聞・雑誌、また特設電話窓口、住民説明会、そして常設展示拠点ということで、今現在、国で示されているのはこういった内容です。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺をお伺いしたいと思います。あわせて、先ほど将来さらなる増便につながることが明らかな新ルートに対して反対をしてほしいということで、そちらもお伺いします。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"この新聞・雑誌ですけれども、こちらは今委員ご指摘のように、新聞・雑誌はこれからの新たな情報として伝達をされるものだと認識をしております。 日付は失念してしまったのですけれども、実際に羽田空港のこれからという部分の掲載は、新聞でしておりました。例えば説明会を開催します… これも再三申し上げておりますとおり、現状においては、今は賛成・反対というようなことを区として言う状況ではないと考えております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは説明や要望をしても、実行されない、返事もないという事態が山ほどあるなということが浮き彫りになっていると思います。ぜひ品川区議会でも委員会でもこうしたことを行うべきだし、国に来てもらおうということを要望したいと思いますけれども、いかがか尋ねました。","respondent":"鈴木（ひ）委員長","answer":"国土交通省がどう考えるかというところの質問を、区の課長に答えていただくということも多々あると思うのですけれども、ちょっと正副で検討をさせていただきたいと思います。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも品川区も、品川区としましては、この舟運事業・水辺活用事業に与える著しいこの悪影響をどうお考えなのかということをまず１点お伺いします。ぜひとも一度冷静に立ちどまって考えていただきたいということで、国からのご回答を求めていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"この舟運事業というのは、区といたしましても非常に重要な事業なので、区としての施策の一つであると認識をしております。ただ、やはり区が考えるのは区民の皆様の日常生活も非常に大事だということで、そしてしかるべき対応を求めてまいりたいと思います。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問・要望","question":"まさに呼ぶだけではなくて、呼んでからの中身が大事ということをぜひとも強調したかったので、このお話をさせていただきました。ぜひとも国に今までの議論、そして具体的な回答を求めていっていただきたいと考えておりますので、なにとぞよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"あべ委員","kind":"提案","question":"その時期、品川区としてやはりこの羽田空港新飛行ルートの問題についてきちんと担当を置くということもひとつ提案させていただきたいと思うのです。品川区としての要望がきちんと対等に出せるような体制づくりというのも区として行っていくべきではないかと思うのですが、いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"羽田空港にかかわる区の対応の仕方についてですけれども、これはこの後もずっと引き続き行われていくわけですので、そうした中で。いずれにしても、しっかりした対応だけは欠かさずできるようにしていきたいと思ってあります。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問・要望","question":"意見を先に述べするのですけれども、２０１４年６月でしたでしょうか、もうかれこれ３年前だったと記憶しています。多分私どもの委員会から要望が挙がったことに関しましても、しっかりやっていただいている、私どもも研究を重ねていっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"引き続き当然議会として求めるところですので、引き続き今期の行財政改革特別委員会の中では継続して審議をしていけばいいかなと思います。ただ、平成２８年請願第８号については、ではそのときに言ったほうがいいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"数もそうですし、反対の多さもそうなのですが、改めてそこにみっちりとその思いが意見としても書かれております。よって結論を出す、採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"この問題が始まって以来もう随分と何回にもわたって請願・陳情をいただいていて、一つ一つの気持ちを本当に受けとめていきたいと考えています。今ここで採決をしてしまうと、どちらかというと私どもは区に対して、ここはちょっと技術的な意味から継続というふうに主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"今中止を求めないと、このまま既成事実として進んでしまうおそれがありますので、ここで中止を表明すべきだと考えております。したがって、採択でお願いを申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あべ委員","kind":"意見","question":"これを継続とすることが論理的にあり得るかどうかという、ちょっと私も皆さんのご意見を聞いてみないとわからないなと思っているのです。どのような結論を出しても、この概算要求にはという部分がありましてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"若林委員","kind":"意見","question":"こういう時期で既に平成２９年度予算が国会に計上されていると、まずご本人に委員長のほうから問いかけしていただいて、取り下げるのかどうかという問いかけもあるかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"渡部委員","kind":"確認","question":"先ほど申し上げましたように、取り下げていただくですとか、請願者の方々にご確認をいただいてということでいいのではないでしょうか。請願者にご意思を確認するというところの落としどころにしておかないと、やるかやらないかと言ったら、継続できないので不採択になると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-02","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、公園内の保育園の活用ということで報告がありましたけれども、現在まだ検討中のものとかはあるのか尋ねました。","respondent":"柏原企画調整課長","answer":"それから保育園というのを検討はしていますが、国家戦略特区を使うかどうかというのは、いま少し議論が必要だと思ってあります。そういったところも考えながら、いろいろなケースを考えながらということで、そういった法制度の動きを見て検討は進めているという状況です。","id":"exchange-050"},{"speaker":"新妻委員","kind":"確認","question":"公園内の保育所のことで、１つ確認をします。この２月１０日に正式に決定をしたということで、平成３０年４月１日よりも前に開園をするということが考えられるのかどうか確認をさせてください。","respondent":"柏原企画調整課長","answer":"東京圏国家戦略特区域会議で認定を受けるべく準備を進めてここまで来たというところではありますけれども、なるべく早い開設というのは区としても考えたいというところではありますが、努力はしていきたいと思ってあります。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"素朴な質問なのですけれども、９２人定員ではなくて、これは何か制約があってのことだったのでしょうか。園庭と言わず、より多くの子どもたちが通えたらいいなと思ったのですけれども、いかがなのか尋ねました。","respondent":"柏原企画調整課長","answer":"探していた時に、いろいろそういったことを考えたときに、樹木を伐採してまでできるかどうかという課題が一つ出たところです。そういったところをうまく使いながら、検討する中でもろもろちょっとそういった制約もありながらということで、結果的にはこういうことになったです。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"隣の荒川区が１６０人程度というのを見ると、もうこれで、予定とありますが決定なのでしょうね。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"最終的に１６０人の定員が増えるのは、この図で言うと、要するに西尾久保育園の更新が終わった後という意味ですよね。３年、４年がやはり大きな目標なので、そもそも対象としてあるのかどうかということも含めて教えていただきたい。","respondent":"柏原企画調整課長","answer":"区も、これは公園を使うということで国家戦略特区ですのであれですけれども、考え方としてはそういうところでも検討というのはしているところです。プラス、基本的な考え方は我々も同じような考え方で、やれるとかできないかというのは検討しているものはあるというのは事実です。","id":"exchange-054"}]},{"id":"topic-03","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"安易な建替え圧力に軽々に飛びつくべきではないのではないかと感じておりますが、いかがでしょうか。それぞれ区のお考えを伺えればと思います。","respondent":"柏原企画調整課長","answer":"それから、どういった形で有効活用、いろいろなところに活用できるのかという視点で検討していきたいというのがここに記載した内容です。防災拠点、これはそういったことだと思いますので、そういったところを鑑みながら検討は進めていきたいと思ってあります。","id":"exchange-055"},{"speaker":"筒井委員","kind":"確認","question":"１つ確認なのですけれども、五反田文化センターはこの類型のどこに入るのかということと、あと品川荘はこの類型のどこに入るのか、お知らせください。","respondent":"柏原企画調整課長","answer":"五反田文化センターは、この類型で言いますと６ページの文化・スポーツ施設の類型に入ってまいります。区民・集会施設のところの中に類型を分けてあります。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり運動系だけではなくて、もっと文化系のこともしっかりと品川区のアピールポイントとしても伸ばすべきものだと考えております。その点、現時点でどうお考えなのか、五反田文化センターと品川荘についての今のご見解を説明を求めました。","respondent":"柏原企画調整課長","answer":"今、その内容につきましては所管部門のほうでも考えながらということで、更新できるものは更新していくということになろうかと思います。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問・要望","question":"ここの骨子にも書いてあるとおり、メリハリを持った公共施設等総合計画にしてほしいと求めましたので、よろしくお願い申し上げます。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"なぜパブリックコメントをやらないのか、やらないとしたらその理由は何なのか、お伺いしたいというのが１点です。そうした統合ですとか、あるいは売却等で区有施設を減らすということはやはりやめるべきだと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"やはりこの施設をどのように、今後はこの施設はどうあったらいいかというのを検討しながら、複合化や統合とかいった考え方も出てくるというものです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"それというのは、空いたところはどうするつもりなのですか。もっと言えば、そうした減らすための統合ということであればやるべきではないと思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それから需要はどうなっているのだといったところをゼロベースで考えながら、もっと有効活用できないかという意味合いで統合・複合と考えています。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、そちらのお考えはいかがでしょうか、伺います。導入を検討すべきだという区の、なぜそのように考えているのかお伺いするのと、現実にこれまで品川区への適用事例などはあったのか尋ねました。","respondent":"柏原企画調整課長","answer":"ただ、いろいろな手法を検討する中で、区にプラスになる部分というのがないかというのは常に検討したいです。特にＰＦＩのところでは、仮に導入を検討するにしても、もうこの手法でしかないということではないというのはご理解いただければと思ってあります。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"「免震化で平成４４年から４５年まではもちます」という話もありましたが、さらなる耐震化や免震化、補強の考えはあるのかどうかをお伺いします。そこら辺の考えをお伺いします。","respondent":"柏原企画調整課長","answer":"ご意見の伺い方の手法というのはさまざまあると思いますので、いろいろな形を検討したいと思ってあります。品川区は品川区のあり方の検討をしていきたいと思ってあります。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"これも一般質問などでもやらせていただいたのですが、区営住宅は非常に求められておりまして、戸数をその結果減らすということは入っているのか。私は増やすべきだと思うのですけれども、その考えも入れていくべきだと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"公営住宅に関しましては、その集約化・複合化を区の住宅でする際に、どういった形にするのがいいのかというのは検討すべきだろうと思ってあります。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"建築を始めるとやはり３年はかかるわけですから、実は待ったなしの建物というのが私はいっぱいあるとは思っています。この計画が出た段階において、一回区内をゼロベースで見直していこうというようなお考えがあるのかどうか、ちょっとそこを説明を求めました。","respondent":"柏原企画調整課長","answer":"委員が今おっしゃるように、表現、言葉の使い方につきましてはちょっと検討させていただきたいと思ってあります。それから、先ほど施設の類型ごとにご説明をさせていただいたところですけれども、一旦クリアにする中で考え方を整理していきたいとは思ってあります。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"その際には転用もそうですし、場合によっては売却も必要なことですから、当然視野に入れていくべきだと考えています。そちらのほうがよほど重要だと思いますので、そういうところも複合的に考えて、これからの施策を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問","question":"ソフト的な運用面での縮減とかコストの部分とかいうのを、もっと少し工夫があってもいいのかなと思ったのが一つ、それを今お伺いしたいです。最終的にこれがどういう形で、最終的に公共施設等総合計画をどのような形で出されるかというのをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"基本的な考え方といいますか、中身についてはもう今回ご意見いただきまして、そういったところも踏まえてこの形になろうかと思います。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"どういったところが違うのか伺いたいと思いますし、この素案は今後この委員会の場に出てくるということはあるのでしょうかということを伺いたいと。別の機会で区民の意見を聞いていく場を設けていただきたいと思うのですけれども、それはないということなのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今後その場面というのは、今回はこの閲覧する中でご意見等も伺いたいと思ってありますし、今回のこういったところでもご意見いただいてあります。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"どういった判断になるのか伺いたいと思います。これをしっかり区が責任を持ってやっていくべきだと思いますし、統廃合で福祉の向上につながるのかということも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"１ページのところの「必要な機能」の部分は、それは個々に判断をしながら、これは載せさせていただいたです。その一つの手法として統廃合があったりですので、それイコール、それが充実につながらないというのは当てはまらないのではないかと思ってあります。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして４ページのところで、この「必要に応じて」というのはどういう場合なのか伺いたいと思います。転用とは、先ほど単純になくしていくわけではないというお話でしたけれども、どういった考えなのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"直近のデータで細かいものはございませんが、そういった利用率を見ながら施設の集会機能のあり方というのを検討すべきだろうと思ってあります。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"よろしいですか。私から１点確認させていただきたいのですけれども、この骨子と素案というのはどの程度どう違うのか、ちょっとそこのところをお聞かせいただけたら。","respondent":"柏原企画調整課長","answer":"端的に申し上げまして、これを閲覧するということになります。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"どちらなのでしょうかというのが１点と、普通は骨子ではなくて、この段階だと「骨子（案）」とあるべきなのですよね。閲覧に供するものであれば、やはり「（案）」という字がどうしてもついていなければいけないと思うのですが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"済みません。これは区がその考え方として、確かにご意見を伺って、思いとしてはそういうつもりでお出しをさせていただいたです。","id":"exchange-071"},{"speaker":"あべ委員","kind":"意見","question":"大きく変わるかどうかは問題ではなくて、ご意見を聞くものというのは、たとえ一字も変わらなくても案は案なのですよね。は「素案」、名称はどちらでもいいのですが、案という文字がついた形で提供されるのがよろしいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"あべ委員","kind":"質問","question":"それを踏まえた上で、大きく２点、枝問もありますが伺いたいと思います。平成２７年度の数字がこの平成２９年３月、今の時期になってこれが報告されるというのはどういうタイミングだったのか尋ねました。","respondent":"柏原企画調整課長","answer":"先ほど、ご説明の前に若干触れさせていただきましたけれども、正直なところかなり試行錯誤したというところがあります。予算編成に向けての一つの仕事を進めるにあたってこういう指標が出るというのは、これはもう少し充実させて活用していきたいとは思ってあります。","id":"exchange-073"},{"speaker":"あべ委員","kind":"意見","question":"いい試みだと思います。やはりこれを今後どうしていくのか、あるいは人員体制ですとか事業のやり方ですとか、いい形で改善に結びつけてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"基本目標１について、大きく２点お伺いしたいのですが、なぜこのように上げられたと区は分析しているのでしょうか。そこら辺の区の認識をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"２つ目のほうはちょっとかなり個別かもしれないので、難しいかもしれないです。基本目標のところだけはちょっとお答えしていただきたいのです。","respondent":"柏原企画調整課長","answer":"１５歳から４９歳までの女性が１人当たり一生で何人のお子さんを生むかというのを統計上あらわしたのが、この合計特殊出生率ということになります。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"区としてはこの１.４５というのをどういうところで達成していこうとお考えなのでしょうか。私はちょっとどうかと思うのですけれども、どうやってこの１.４５を達成しようとしているのかというところをお伺いします。","respondent":"柏原企画調整課長","answer":"基本的な目標の１番目にしていますので、そういった考えのもとに施策を打ちながら、この目標値に向けて頑張っているというものです。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"あまりにも抽象的過ぎて、どうやって安心して子どもを生み、楽しく子育てできるまちをつくるためのどのような施策を重点に考えているのかというところをやはりしっかりご説明していただかないと、ちょっとわからないので、もう少し具体的にお願いします。","respondent":"柏原企画調整課長","answer":"こちらに出ている施策です。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"基本目標１のところで、先ほど中学生以下ということで説明されていたのですが、そこの確認をさせてほしいと求めました。","respondent":"柏原企画調整課長","answer":"先ほどはちょっと言い方がわかりにくかったのですが、こちらのほうは長子、一番上のお子さんが小学生または中学生である区民の方を対象とした数字をとっているものです。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところもやはり入れて子育てしやすいということになってくると思うのですけれども、お考えを伺いたいと思います。この最終目標が５００人ということで、これはやはり上方修正も含めて考えてほしいと求めましたが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"会場のキャパシティとか、いろいろそういったところをトータルに考えた時に、この目標値を設定したというものです。見直しも常にしているところがありますので、よりよい数値があればそういったところに変えていくというのも一つ考え方としてはあろうかと思います。","id":"exchange-080"}]},{"id":"topic-04","title":"はじめに(1)議会閉会中継続審査調査事項","agenda":"はじめに(1)議会閉会中継続審査調査事項","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"３つ目に対しては、１つ目の国家戦略特区と４つ目の補助金・助成金については一切言及をしないということなのか、いかがなものか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/502896?Template=document&Id=6024#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":93824,"voices":219}},{"id":"h29-20170302-18","meetingId":"h29-cm03","date":"2017年3月2日","dateIso":"2017-03-02","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時４２分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"いながわ委員","kind":"提案","question":"それともホッケーの会場というのですか、園内の移動手段も含めて、どういう考えでいらっしゃるか。答えようがないと思うのですけれども、必要ではないかと私は思うのですが、どうか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会本番中の会場内部の運営につきましては、全て組織委員会が責任を持ってやるという役割分担です。その他、ご指摘いただきましたセグウェイのことですとか、新たな活用についてもまだこれからと認識しています。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"大井ふ頭中央海浜公園のホッケー会場のところはいろいろな競技施設があるわけですが、ホッケーの開催期間中はほかの競技場の使用はしないのかなと。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会期間中の公園の中身につきましては今まさに検討中ということは聞いておりますが、おそらく公園全体が閉鎖される形になろうかと思います。いろいろな意味でオリンピックのために使うという形になろうかです。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"改めて確認といいますか、小川課長と池田課長に質問しますけれども、特別委員会は、今年度、今日が最後になりますよね。行かれたことについて、どういうふうに活用していくのだという、心構えも含めて具体的に教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"４月は人事異動の時期ではありますが、昨年、確かにリオの視察をさせていただきました。２０２０年に向けて、継続性に欠けるようなことがないように、万全を期して臨んでいきたいです。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"質問ではないです。改めて予算特別委員会でこの辺はじっくり伺っていこうと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"ご提案があり、提案なのですけれども、もしくは競技のチケットにそのデザインを活かしてほしいというご意見がありました。ぜひ品川区からそういう声を挙げていただきたいということで、こういう提案をさせていただきましたので、追加として入れてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"意見","question":"今日、ぱぱっと見るというのも何かちょっと落ちつかないので、読み上げるというのはしていただいたほうがいいのではないかと思います。私が読んでも構わないけれども、お願いしたいと思いますとの意見を述べました。","respondent":"渡辺委員長","answer":"区民参加が最も見込まれる２０２０年、あるいは議会全体のそういう思いを理解いただこうということで、項目立てをいたしました。説明と朗読を兼ねさせていただきました。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"この１年間かけて議論してきたことの多くの部分がまとめられているかなという気はするのです。東京都オリンピック・パラリンピック準備局長宛てに出すとされているこの要望書との関係はどういうふうに整理したらいいのかなというのが。","respondent":"渡辺委員長","answer":"進行上、まとめのご意見の説明が終わった後、東京都への要望書については、この後すぐ、皆さんにご説明をして、諮らせていただきます。ほか、いかがでしょうか。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問・要望","question":"確認なのですけれども、これ１枚を提出するのではなく、こういうことをやりましたよと議長に提出すると。いいかどうかはわからないですが、委員長としてどうお思いか、もしおありでしたら説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まとめのところを見ると１２項目、各会派からのさまざまな要望があって、こういう形で提出されることになるのでしょうか。まとめ方というか、この項目の中で、それに関してこの１行に集約していくというところの意味を説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"今こちらの一覧の中にも１２月１日の追加というところで入れさせていただいているのですが、また、追加項目の中にも入れしています。ぜひこのまとめの中にも動画によるバリアフリーの情報提供という１文を検討ほしいと求めましたので、正副で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/931440?Template=document&Id=6510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":13566,"voices":41}},{"id":"h29-20170306-3","meetingId":"h29-c-budget","date":"2017年3月6日","dateIso":"2017-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を183件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川区は１,７０７億円余というこの補正予算の中で、その辺を踏まえてどういうふうに考えているのか、１点お聞きしたいと思います。本会議の中でも質問させていただきまして、そのときは健康面ということでお聞きしたのですけれども、その辺を含めて説明を求めました。","respondent":"黒田税務課長、中山障害者福祉課長、米田人事課長","answer":"これは減も見込んで納税義務者が増え、全体として当初予算より１０億円余増収であろうということで、補正予算として計上しているものです。４月には… 児童発達支援につきましては、そして障害児通所支援、主なものは放課後等デイサービスの給付費の伸びによるものです。… 前年度が１１.８時間だったところ、１２.３時間ということで、１人当たり０.５時間の伸びを見せてあります。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、平均すると０.５かもしれないですけれども、一部の方に負担がかかってしまっているのかなというふうに感じるところです。世の中で騒がれている中で、その辺、もう１回お答えをお願いできますか尋ねました。","respondent":"中山障害者福祉課長、米田人事課長","answer":"平成２６年から平成２７年度が２.１倍、平成２７年から平成２８年にかけては１.２倍というような伸びにもなってあります。実は今、放課後等デイを利用されている子どもは２６９名いらっしゃるのですが、まだ伸びが想定されるところで… ありましたように、特に一部の職場で一部の職員による残業時間の増ということが、やはり傾向として毎年見てとれます。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"通所に関しては、これからも必要に応じてやっていっていただきたいのと、対象の方の要望に応えるようによろしくお願いします。この３年間で１万人以上の転入が入っているので納税義務者は増えているのですけれども、そこら辺のところをどう捉えているのかを説明を求めました。","respondent":"黒田税務課長","answer":"納税義務者における年齢のところですが、７０歳以上の方でありましても、納税義務者につきましては平成２７年と比較すると、やや増、６０歳台でも増ということでありますので、平成２８年度のところにおきましては、納税義務者については、この年代についても、やや増加傾向です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"税務面だけではなくて、１万人以上の方が品川に入ってくる、つながりについては区としてどういうふうに考えていくのか。その１万人ぐらいの方のニーズをどのように捉えているかということについてお答えをほしいと求めました。","respondent":"柏原企画調整課長","answer":"そういった中で、今まで住んでいる方々との地域間での連携といいますか、これをどう捉えるかというのは、１つ課題だというふうに捉えております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ただ、やはりこれだけの人数が増えてくると、なかなか関係がうまくできない、その辺を区がどこまで手伝えるのか。新しい方にそこに入っていただけるためにどのように考えていくのか、その点をもう１回、お答えをお願いしますとの意見を述べました。","respondent":"柏原企画調整課長","answer":"こういったところのまちづくりをどういうふうにしていくのだという考え方について、区のほうでもまちの方々とご一緒に検討していこうというような予算も立ち上げておりますので、積極的に入っていきたいというふうに思ってあります。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう形で区として立ち上げていっていただきたいと同時に、１つの町会で大変な人数の多い町会も出てきています。新たにどんどんマンションが建っていく中、大変な苦労もあると思いますので、その辺も区としてご協力していただければ幸いだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"６７ページの出産・子育て応援事業、５８ページ、戸籍事務費、５６ページ、広報広聴費に関して伺っていきたいと思います。理由をお聞きしまして、それは育児パッケージの経費だけなのかどうか、このあたりを説明を求めました。","respondent":"太田品川保健センター所長","answer":"全体の予算の中身としましては、人件費や一般需要費としてチラシ等の印刷代等も含まれております。それに主なものとしては、カタログギフト代が含まれております。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"この育児パッケージというのが、そのカタログのものだということでよろしいのですね、わかりました。そのときは５カ月で、どのぐらいの対応なのかということを改めて伺っていきたいと思うのですが、ネウボラネットワークの対象者は誰になりますか。","respondent":"太田品川保健センター所長","answer":"妊娠期の方から就学前の子どもをもつ全てのご家庭ということになります。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"平成２８年度の６月からは、出産されて１カ月後までに電話して様々状況を確認するということもやられていると伺っています。全員なので１００％だと思うのですけれども、その上で改めて、何％の見込みがあるか説明を求めました。","respondent":"太田品川保健センター所長","answer":"１月末の妊娠届出に対しては、大体７５％の面談率となっています。","id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"平成２７年度が８１.７％の訪問率ということで、やはりそこの数字を超える、ないしそれと同じぐらいをしっかりと目指していく。会える会えないはあると思うのですが、もう１回確認ですけれども、どのあたりまでをしっかりと目標にして取り組まれているか説明を求めました。","respondent":"太田品川保健センター所長","answer":"他の自治体の妊娠中の面談率を聞いたところによりますと、６割から７割の後半ぐらいまでというふうに聞いております。妊娠届出の８５％しか出産には至らないのですが、出産した方に対しては、９割近くまで面談ができるのではないかと考えています。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"今年の決算等でしっかりと確認をさせていただきたいと思うのですが、そして安心の子育て、相談体制のより一層の充実が必要かと思います。当然これは利用者の方のお声ですから好意的な声が多かったわけでありますが、その上で、数字上の利用実績について教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"宿泊型につきましては、２月末現在で、ＮＴＴが１０件、聖路加が１件、東芝病院が２件、昭和大学が２件ということになっております。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"合計すると１５件でしょうか。１０件、１件、２件、２件だったと思います。","respondent":"太田品川保健センター所長","answer":"失礼いたしました。東芝病院が３件で、１６件でした。","id":"exchange-013"},{"speaker":"つる委員","kind":"確認","question":"２月末現在で１６件ということで、１０％では３６０人ぐらいとなって、今の１６名は数が相当少ないのかなと。このあたりの確認と、品川区内で初産の方の人数が、平成２５年から平成２８年ぐらいの年度でもしわかれば説明を求めました。","respondent":"太田品川保健センター所長","answer":"聖路加産科クリニックの件数の伸びが少し少ないなと考えていますが、出産を迎えまして、もう少し増えていくのかなと考えています。８割を占めておりましたため、家族の支援が得られないという方で、かつ初産ということにしております。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"チェックマークがあったりするのですが、それをどう正確に把握していくかというところと、本人申告による性善説であるところ。ですので、対象者の要件の緩和等の検討も必要だと思いますが、このあたりはいかがお考えか尋ねました。","respondent":"太田品川保健センター所長","answer":"初産の数ですが、平成２７年度は３,７３８人に対して２,２４５人ということで、大体６割の方が初産ということになります。検討しますが、ご家庭で手伝ってくださる方がいる場合には、ご家庭での支援をやっていただくというのが順序ではないかと考えています。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"予定していた他の質問は別の款でやりますが、またこのことについても他の款でしっかりと進めていきたいと思います。充実、安心の子育てができる品川区ということをしっかりとこれからも構築していただきたいということで、これからも応援していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"国、そして東京都に、項目としてあるのかどうか伺いたいと思います。この公設公営の区立保育園に係る国からの一般財源分というのは、歳入のどこに、そして幾らあるということになるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長、秋山財政課長","answer":"区立保育園に対する建設、運営の補助金ということですけれども、これは公設の保育園の建設および運営に対する補助金はございません。 公設公営の保育園への国の補助は、基本的にはございませんので、どちらに入っているということもございません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"平成１３年の閣議決定で、東京都もゼロと、そういう仕組みだということだと思います。ならば、なぜ国や都に建設や運営費に係る支出金も求めないのか、その理由を伺いたいと思います。","respondent":"秋山財政課長","answer":"公設公営の保育園への補助ということで、現時点では国や都からは何もないです。国からは地方交付税というところで措置をされているというふうに考えておりますので、特別区とはちょっと事情が違うのかなというふうに思います。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺ったのは、なぜ国や都に建設や運営に係る支出金を求めないのかと伺ったので、そこを伺いたいと思います。保護者に保育園保育料の値上げを求めたり、保護者には求めますけれども、国や都にはなぜ求めないのか理由を伺いたいと思います。","respondent":"秋山財政課長","answer":"特別区から全国市長会等の要望の中に、そういう子育てに対する財政支援は要望はしておりますので、全くそういうことをしていないということではないと考えています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"４月入園の待機児ゼロというこの問題についても伺いたいと思いますけれども、そもそも区長の公約ですから、とても大きな課題だと私は思っております。３つ目、この３点を原因だと言うのであれば、それぞれ伺いたいと思います。","respondent":"秋山財政課長、大澤待機児童対策担当課長","answer":"国や都への要望ですけれども、子育てを支援するという国の政策、東京都の政策の中に、大きく区分けをして、区としても要望はしています。国のほうで新たに６月に待機児童解消プランを決定するですので、新たな対策によりまして、解消が進む可能性はあると思います。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"今になって予想しがたかったということは、区のまちづくりの失敗だということでしょうか、この点を伺います。なぜ働きたいという女性が増えていること、この思いを理解することができなかったのか、理由も伺いたいと思います。","respondent":"稲田都市開発課長、大澤待機児童対策担当課長","answer":"子育て支援施設や高齢者福祉施設の整備促進を積極的に図るということで、拠点整備を行っております。子育て支援施設等もつくっていくというところで、区とも協議しながら、現在はやっているです。 待機児童がゼロになるかどうかですけれども、平成３０年度のゼロを目指して努力は続けてまいります。それはもちろんこれからどんどん増えていくということは予想しておりましたので、それにあわせて前倒しで開設を進めているところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"そう説明するならば、なぜ人口一極集中を招いたことが予想しがたいことだったという答弁になるのか、そこを伺いたいと思います。そもそも待機児が解消されない理由について、必要な保育園が足りないことだということを区は原因と捉えているのか伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"これだけやっている区はありません。ぜひこういったところを踏まえて区政を語っていただければということをお願いしたいと思います。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、人気区だから対策が追いつかないのであれば、では、人気をなくすのですか。このことへの反省がなぜないのか、その点についても伺いたいと思います。","respondent":"齋藤子ども未来部長","answer":"区政７０周年を迎えまして、区だけではなくて、区議会との両輪となって待機児童対策を進めてきたからだと考えております。脱輪するというのではなくて、これからも待機児童対策をしっかりと取り組んでまいりますので、ご理解のほどお願い申し上げたいと思います。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"あまりにも私の質問に対して誠実な答弁ではないと、その点だけは指摘したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"このような７,３５０万円増となっているのか、その内容についてお伺いしたいと思います。あわせて、４７ページの都補助金の公園・児童遊園整備についてですが、まず、この６００万円減になっている理由、内容についてお伺いします。","respondent":"溝口公園課長","answer":"そこの用地買収費、そちらを国費の対象に充てておりまして、その増分が一番大きな増額の理由になっております。スポーツ施設整備費の６００万円の減額ですが、次年度に工事を送るため、今年度につきましては減額という形での補正を組ませていただいたものです。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"この７,３５０万円には、そういう意味があったということで初めてお伺いしました。現在、しながわ区民公園のトイレについて、どういう形になっているのかお伺いしたいと思います。","respondent":"溝口公園課長","answer":"しながわ区民公園の整備につきましては、当初、トイレの整備も今年度中に２カ所ほど終わらせる予定でおりましたが、契約の不調等、また保守の見直し、そういったところで全体計画を見直す中で、次年度、平成２９年度に予算計上させていただいて整備を計画しているものです。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"次に、歳出の７５ページの公園・児童遊園整備について伺います。管理棟改築実施設計委託でも１,６００万円の減となっておりますけれども、当初予算より全体的に減少している原因について伺いたいと思います。","respondent":"溝口公園課長","answer":"今回、公園整備事業費に関する減です。全て設計委託を行っているものでございまして、大きい理由といたしましては、契約差金が一番大きな減額理由となっているものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問","question":"次に、４３ページの国庫補助金のいじめ防止対策費について伺います。そうした中、補正予算の国庫補助金では、財源更正によって２１７万２,０００円減少しておりますけれども、その理由について伺いたいと思います。","respondent":"溝口公園課長、村尾教育総合支援センター長","answer":"今回の委託です。それぞれ違う業者が今年度末のまとめに向けて事業を進めているという形になっているものです。 平成２８年度当初予算においては、品川学校支援チーム「ＨＥＡＲＴＳ」の３名分の雇用経費を補助対象として想定しておりました。来年度も含めて、いじめ防止対策を含めて、ＨＥＡＲＴＳの取組みを進めてまいります。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"子どもたちの理解を深め、日本人として誇りを持ってもらい、また日本のよさを発信する能力や態度を育成する教育であると伺っております。そこで、１５０万円減について、なぜ東京都はこの事業に対して減額を行ったのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"平成２８年度当初予算では、５校で１校当たり５０万円として予算計上を行っておりましたけれども、その兼ね合いで５０万円の交付基準が減額され２０万円となったと聞いております。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問","question":"委託事業ではあるのですけれども、本区としてどのように進めていくのか。その減額した分は、何か対策を行うのか、先ほどと同じような質問になるのですけれども、影響は出てこないのか、もう一度お願いいたします。","respondent":"熊谷指導課長","answer":"ですので、この伝統文化推進につきまして課題が生じたということはございませんでした。反対にオリンピック・パラリンピック教育とあわせて充実したというふうに考えてあります。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"東京オリンピック・パラリンピックも控えているので、ぜひ日本の良さを、また品川の良さを今後も発信できるよう力を入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"補正予算という意味でお伺いしたいのですけれども、まず初めに、改めて補正予算の位置づけや意義についてお伺いします。それと今回、トータルで４億７,６００万円余の減額補正となっていますが、ご自分たちではどういうふうに評価しているのかお伺いします。","respondent":"秋山財政課長","answer":"今回ご説明させていただきましたように、最終年度末に当たりまして、予定を変更せざるを得ない経費をもとに編成をしたものです。その額が当初予算との差が大きいからどうとか、低いからどうとかということは、私どもとしては考えてございません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"トータルでは４億７,６００万円という形なのですけれども、すごい増額、減額が激しいのです。今回の補正で増額分で幾らか、減額分で幾らか、また、それはそれぞれ何％に当たるのかお伺いします。","respondent":"秋山財政課長","answer":"例えばやむを得ず変更するということで大きなものが、補助１６３号線ですとか、ハード系のものは国との予算の関係で減になっているものが多いです。１つ１つ増の理由、減の理由はそれぞれございまして、今回の集計になったというふうに考えているものです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"その辺について改めてお伺いしたいのと、かつて補正予算で計上したものの、次の補正予算で減額したものがあったと思うのです。ですから、そういう意味においても、精度の高い当初予算としていかないといけないと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"秋山財政課長","answer":"それなりの理由があってやっているというものでございまして、補正予算を立てたから必ずやるのだというようなことは考えておりません。合理的な理由があるということにはなりますけれども、その理由に基づいて予算の減額、増額を議会でご議決いただくというのが基本的な姿勢です。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"６５ページの障害児通所支援についてお伺いしますけれども、まず１点、それでいいのですかということです。もう１つは、難しいという答弁だったような気がするのですけれども、障害者福祉課はどういうお考えであるかお伺いします。","respondent":"佐藤保育課長、中山障害者福祉課長","answer":"医療的ケア児の受け入れに関してですが、法改正の趣旨や医療的ケア児の増加等から、受け入れに向けた課題の検討を行ってまいります。 医療の必要なお子さんの療育の件ですが、現在では、城南分園のほうで行っております。これをこの４月から新たに１つ事業所をつくって、医療の必要な子どもの療育ということでは障害者のほうで対応していく予定です。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"障害者福祉課長、それは前向きな答弁ととっていいのでしょうか、後ろ向きな答弁としてとっていいのでしょうか。これが前向きであるならば、本会議の答弁とは違うと思うのですけれども、その辺について、はっきり答弁していただけますか。","respondent":"中山障害者福祉課長","answer":"障害者福祉課の立場でいきますと、子どもに対しての療育支援というのは、基本的に障害者福祉課の仕事だというふうに考えております。働く親に対する支援というのは、保育課のほうの支援になってくるというふうに考えているところです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"この結果的に２００億円になるのですけれども、この目標額は幾らなのでしょうか。その基金の積立額の目標と、これから改築が必要な学校の改築費の総額を、大まかでいいので説明を求めました。","respondent":"秋山財政課長、篠田学校計画担当課長","answer":"義務教育施設整備基金のお問い合わせということでお答えいたしますけれども、今回、３０億円を積み立てております。年間３０億円が必要だということで、３０億円の基金の積み増しをしたと、そういう考えです。 今、残っている学校が全部で２６校ほどあります。直近で大体１校当たり４０億円前後の金額がかかってまいりますことから、そのぐらいの金額がトータルでかかるものというふうに考えているところです。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"積立額の目標と、これから改築が必要な学校の改築費の総額を教えてくださいと言ったのに、答えていないですよね。意図的に答えていないならあれなのですけれども、これ、わからないのだったら、総額もわかっていないのに３０億円を積み立てているのか尋ねました。","respondent":"秋山財政課長","answer":"その３００億円というのは目標ですけれども、そこには３００億円を目指して毎年３０億円使っていくというのが目標とお考えいただければと思います。要するに、積立額の総額なので、残高ではないというふうにご理解いただければと思います。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"次が、どうしても伺わないとならないことで、ページ数だと７５ページ、天王洲公園改修工事なのですけれども、今年度は設計段階なのでしょうか。オリンピック・パラリンピックに向けたものがあるかどうかお伺いします。","respondent":"溝口公園課長","answer":"今回、減額補正したものにつきましては、来年度以降のＡ・Ｂ面の人工芝の張替え工事、また管理棟の建替え、そういったものをやっていくものです。オリンピック・パラリンピックの情勢、今後のスポーツ利用促進という観点もあわせまして、改修工事を進めているものです。","id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"その辺、どういう形で所管の課と、いらっしゃいますか。オリンピック・パラリンピックの担当課長として、この天王洲の公園、どういう思いがあったか、時間、最後までいいので、お願いしますとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"天王洲公園につきましては、ブラインドサッカーの国際大会を目指しているところでございまして、そういった意味で、オリンピック・パラリンピックが終わった後も天王洲公園を活用するというふうに考えているところです。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"７３ページ、そして７７ページ、防災街区整備事業の中延二丁目旧同潤会地区について質問させてほしいと求めました。初めに、橋梁長寿命化修繕計画、この内容についてお知らせほしいと求めました。","respondent":"多並道路課長","answer":"長寿命化計画は、平成２２年に、今後の橋梁等の管理を長寿命化させるために、維持管理により長持ちさせたいという観点で計画を立てたものです。平成２７年にそれを改定いたしまして、現在、その計画に基づき、計画的に修繕工事を行い、平成２８年度はその内容で行ったものです。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今現在、勝島橋、昨年、平成２８年９月から、予定ですと３月３１日までとなっておりますけれども、その辺の今現在の状況と、この工事が終わった後、橋梁名の表示など何か示すような、新しくなったことによって何か示されるのかどうかお知らせほしいと求めました。","respondent":"多並道路課長","answer":"そこら辺の関係で、様々な実態を聞きながら、より良い関係に進めていきたいと思います。現時点では、塗装工事、今の維持管理という観点で工事を行っているところです。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、今、塗装工事をやっているということで、今現在は表示を掲げないということでよろしいのでしょうか。おそらく５０橋あると思うのですけれども、他の橋を含めて、キャッチフレーズを橋に掲げてやるという感覚でよろしいのか尋ねました。","respondent":"多並道路課長","answer":"平成２６年度から順次行い、来年度いっぱいで品川区の管理する橋梁については、全て橋梁名を表示しようと考えております。舟運事業全体の進め方のご意見をお伺いしながら、今後、より良い環境づくりは検討していきたいと思っているところです。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この勝島橋のところの競馬場通りなのですけれども、これからホッケー競技が開催されるという中で、今現在、無電柱化を進めております。この橋にかかる歩道も、いずれは整備をしていくという考えでよろしいでしょうか、説明を求めました。","respondent":"多並道路課長","answer":"競馬場通りにつきましては、現在、電線共同溝の工事を今年度末までということで、工事完了予定です。その後、来年度以降、平成３１年度の初頭までに、道路整備工事、最終的に整備工事を行って終わらせるという段取りで進めているところです。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、７７ページの防災街区整備事業の中延二丁目旧同潤会地区について、お伺いをさせてもらいたいと思います。この解体工事を本年の２月から進めておりますけれども、順調に進んでいるのか、その進捗状況をお知らせほしいと求めました。","respondent":"寺嶋木密整備推進課長","answer":"本年２月より予定どおり解体工事が進んでおります。幾つかのブロックに分けて、最終的には５月末までに解体工事を終了するということで、予定どおり進んでいるというように報告を受けております。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで今、解体のヤードといいますか、入口のところはちょうど中延小学校の前のところで作業車が出入りしていると思うのですけれども、時間を見ると、８時から１７時となっているのですが、この８時というのは、当然。","respondent":"寺嶋木密整備推進課長","answer":"お知らせしている時間は、準備や後片づけも含めた時間なので、通学時間を避けて実際には工事をするということで、事前の説明も受けておりますし、実際にそのように進めるということで事業組合のほうから報告を受けているところです。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。第１回目が３月１２日（日）にあると思うのですけれども、詳細について、どういった内容なのか教えてほしいと求めました。","respondent":"寺嶋木密整備推進課長","answer":"実際には、これは２回に分けてやるのですけれども、特に前半のほうは今言ったような放水訓練を中心とした訓練というふうに聞いております。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今現在、整備をされているという中で、区としても様々大変なご苦労があったと思います。これから、今現在、近隣地区の解体工事に伴うことで、何か要望というか、クレームというか、そういうものがあるのかお知らせほしいと求めました。","respondent":"寺嶋木密整備推進課長","answer":"周辺の方に解体の説明会、それから、それのもう少し前に紛争予防条例に基づく説明会ということで実施しております。紛争予防条例による説明会は２回、解体工事の説明会は１回、それぞれ対応しているということで。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４０ページと８０ページ、また７４ページ、今日は１本で確認をさせてほしいと求めました。今日は主に、トイレの洋式化を含めた改善について確認させてほしいと求めました。","respondent":"品川庶務課長","answer":"申請を出していたのですが、これは国の財源の関係で、予算が不採択になってしまったという表記になってあります。学校のトイレですが、今年度につきましては４校、整備をしています。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"和式が４５.８％で私が初めて質問を始めたときには、和式が４６.７％ですから、この５年間で６％ほど改善をされているということになっています。この調査のとおりで現状もいいのかどうか伺います。","respondent":"品川庶務課長","answer":"改修工事を全て終わったという想定での段階で、和式については３６.６％、洋式については６３.４％の比率となっています。ですので、東京都の平均等よりも上回っているような状況です。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回この質問でよく伺いたいのですが、各自治体ごとに今後の、各自治体が選択肢を1)から5)を選ぶようになっています。今回、９０％ということでお答えになっているのですけれども、品川区としてはどういうご見解なのか、そこを確認をさせてほしいと求めました。","respondent":"品川庶務課長","answer":"先ほど委員から説明があったように、概ね洋便器ということで回答はしています。状況も見ながら検討はしていきたいと思いますが、８割から９割前後、洋式トイレにしているというような状況です。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"各トイレに１個残すのかというところを、今後の質問もあるものですから、はっきりしたいなというところが１点あるというところです。もしそういうお子さんがいらっしゃるのであれば、例えば学校に幾つかとか、そういう基準を設けるべきではないか尋ねました。","respondent":"品川庶務課長","answer":"要するに、１個という定義ですが、これは改築校などを見ると、例えば１つの階のフロアのトイレで全て和式トイレというフロアもあります。１階当たり１個という基準ではなく、学校全体として８割から９割を洋式トイレ、残る１割から２割を和式トイレというような考え方です。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"これは品川区としてどういうふうに捉えていらっしゃるのかというところ、現状ではまだそこには全然足りていないのですけれどもいかがでしょうか。都から８３億円ですか、これは区としてもしっかり単費でやっていくのかどうか、そこについてご見解を伺いたいと思います。","respondent":"品川庶務課長","answer":"今後、８割、また９割に向けての考え方というところですが、このトイレ改修、非常に費用がかかります。こういうところも見ながら、かつ補助金の状況も見ながら、トイレ改修については考えていきたいと、このように思っております。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私はこの５年間ずっと聞いてきたわけですけれども、考え方がやはり１つあると思いますので、そこについてはもう一度ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問","question":"６５ページの児童福祉費の職員給与費２億５,６５０万円の減額について伺います。減額の理由は育休と伺いましたが、この範囲は１年間のお休みなのか、どのように育休をとられているのか伺います。","respondent":"米田人事課長","answer":"保育園運営費の更正減額ですが、こちらについては、平成２８年１２月の時点で、育児休業を取っている職員が６２人です。無給の方の人数が増えてくるというような傾向にあります。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"６２人の職員の補完は、どういう形で補充されたのか伺います。","respondent":"米田人事課長","answer":"年度当初から育休に入られるというようなことがわかっていれば、あらかじめ任期付きの職員の採用ということで、育休に入る段階であてがうというようなことと、あとは派遣職員というような形での補充というようなことで主に行っているものです。","id":"exchange-056"},{"speaker":"田中委員","kind":"意見","question":"２０１６年度当初予算が、育休代替経費に約４億６,７００万円計上されていますが、代替職員費助成が約８６０万円です。私立保育園と区立保育園の補助金額の差について、ご説明くださいとの意見を述べました。","respondent":"佐藤保育課長","answer":"私立保育園の運営費に関しましては、公定価格に対して区で約５０％上乗せをして１園当たり約１億４,０００万円の運営費を出しているところです。ただ、その中で収まらない分も勘案しまして、法定外として、先ほど委員おっしゃられた経費について補助を出しています。","id":"exchange-057"},{"speaker":"田中委員","kind":"意見","question":"区立保育園より私立保育園の数のほうが多いので、職員数も多いのかと思います。区立保育園より私立保育園の代替職員が少ないという事実を区はどのように分析しておられるのか、お願いしますとの意見を述べました。","respondent":"佐藤保育課長","answer":"ただ一方で、人によっては考え方で、一度、仕事を辞めてゆっくり子育てをして、その後、戻ってくるというところも聞いております。いずれにしても、処遇改善等、国、都の補助金等も入れてやっておりますので、そういった中でより良い制度になればいいと考えております。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問","question":"品川区全体の保育として、子どもたちの保育の質を保つためにも、保育士の補完、処遇待遇は重要だと考えます。私立保育園の保育士に対しても区として積極的に取り組み、この種の補助金の増額の必要性があると考えますが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"国、都の補助金や都のキャリアアップ補助金等を使って、区としましてはすぐ採択して活用を図っているところです。基本的な考えは、区から出ている運営費に基づいて運営していただくということになりますので、今のところ法定外の補助金の増額は考えておりません。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"たしか２億８,０００万円余のキャリアアップ補助金が品川区にも来ているということでした。２０１６年度より増額されているので歓迎しているのですが、区としては、この補助金がどのように活用されるべきだと考えますか、伺います。","respondent":"佐藤保育課長","answer":"職員に周知を図ること、そして資質の向上の計画策定、実施が必要になっております。その中で計画に沿ってキャリアアップを重ねる上で給料等の改善につなげていくものだと考えております。","id":"exchange-060"},{"speaker":"田中委員","kind":"質問・要望","question":"保育士の給料アップが確実に実施されるような仕組みづくりが自治体には求められています。保育士の手元に確実にわたるような仕組みが品川区でもできているのかということを伺いたいのですが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"その結果、平成２７年度の反映に関しては、約３万８,０００円という、定例会でもご答弁したような金額が出ております。今後も保育士のほうに処遇改善が適切に行くように、調査と私立保育園長会等で働きかけてまいります。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問","question":"６２ページ、３款民生費、１項社会福祉費、１目社会福祉総務費、特別会計繰出金更正減額について伺います。昨年も質問しましたが、この特別会計繰出金更正減額の３つの事業会計の減額の理由をご説明ください。","respondent":"高森国保医療年金課長、永尾高齢者福祉課長","answer":"ご質問いただきました国民健康保険事業会計繰出金、後期高齢者医療特別会計繰出金について、ご説明をします。歳出部分が、医療費総額等が被保険者数の減少によりまして見込みより少なくなったということで… これは消費税が上がる見込みで保険料の率を減額しているものだったのですけれども、それで国と東京都と区で負担をするという制度になっております。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問","question":"難しくて、もう少し具体的に、国と東京都の歳入はどこの事業に充てられて増えているのか。当初予算では見込めない理由はどういうところにあるのか教えていただけますか。","respondent":"永尾高齢者福祉課長、高森国保医療年金課長","answer":"国庫・都支出金の返還金については、説明がわかりづらくて申し訳ありません。国と東京都の負担金が出ていたところですけれども、実際に件数がそこまで伸びなかったというところで返還をするという内容になっております。 ８万３,９３９人ということで、４,８００人ほど数字上では減少を見込んでおりまして、それに見合う形で医療費総額が減少した。それと、収納率もいくらか上昇しておりまして、そちらの様々な要因で繰出金が減少したです。","id":"exchange-063"},{"speaker":"田中委員","kind":"質問","question":"地域支援事業の繰入金ということでしょうか。そして、毎年７億もの補正がかかる理由がちょっとわからなくて、あと仕組み的に、この時期に国と都からの予算がつくのかということを説明を求めました。","respondent":"高森国保医療年金課長","answer":"保険者支援分、法定外の繰入金という形で、最終的に数字としてはこのような数字になっている状況です。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"毎年７億円もの補正がかかる理由を答えていただきたいというのと、仕組み的にこの時期に国と都からの予算が付くからなのかということを教えていただけたらと思います。","respondent":"秋山財政課長","answer":"ここが今、国保医療年金課長がご説明を差し上げた、繰入金と言っても、その中身は様々あります。それ１つ１つについて増減がありまして、それぞれの説明を今させていただいたと、そういうものです。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"それと、当初予算編成時と比べてどうして納税者が増えたと区は分析しているのでしょうか、伺います。地方消費税についても伺いますが、要するに人口増が原因ということなのでしょうか、伺います。","respondent":"黒田税務課長、秋山財政課長","answer":"特別区民税の納税義務者数の伸びの見込みですが、平成２７年度の決算のときの見込みに加えて納税義務者を見込んでいたわけですが、その伸び。平成２７年中の失業率等が低下しておりますので… 交付の見込みが７.９％増ということで、東京都として、東京都全体の消費税が７.９％増というふうに見込んでいるというものです。その両方の要因で増えているというものです。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"これを合わせた人口ですが、７,５７５人から１万５,４９９人と、まさに２倍になっているのです。改めて伺いますが、再開発と税収増との関係を区はどのように考えているのでしょうか、伺います。","respondent":"黒田税務課長","answer":"再開発と税収増の関係というお尋ねですが、基本的に仕事をされている方の年代が転入されてくれば、当然収入を得ていらっしゃいますので、税が増えるというような関係にありますので、所得稼得層が増えれば税収が増えるというような関係にあるというふうに認識しているものです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"なぜなのかと思ってしまうのですけれども、品川では子育てできずに区を離れる世帯が多いということではないのでしょうか、いかがでしょうか。考えを伺います。","respondent":"柏原企画調整課長","answer":"この平成２７年、平成２８年、進めてきたところです。現在、増加の傾向に向かっているということが現況でございまして、そういったところの施策を進めた結果ではないかというふうに思ってあります。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"理想の子どもの数を実現するために今後品川区が取り組むべき点はという質問がありまして、保育施設など子育て支援の施設が充実するとあります。保育園整備があまりに追いついていないというのが子育て世代流出の最大の原因だと私は思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"こちらの人口ビジョンをつくった際に、平成２７年度に策定して、その前の年度ということで、人口等の集計をかけたものです。こういった人口ビジョン、それから統計をとったものが１つベースといいますか、糧になって動いているというふうに認識しています。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"アンケートで、そうした子育て世代が子どもを産むために一番必要だとしている施策に対しては、やはり不十分ではないかと私は伺ったのです。保育園整備が追いついていないということが、子育て世代が離れてしまっているという原因だと思いませんかと伺ったので、もう一度伺いたいと思います。","respondent":"柏原企画調整課長","answer":"保育園につきましても、これまでも重点課題ということで取り組んできたものです。その後、増加の傾向に向かっているというところがありますので、私たちの施策が奏功してきたものだというふうに思ってあります。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"４月に待機児を生まないために緊急対策に使うなど、やはり目の前の喫緊の課題に使うべきだと思うのです、それはいかがでしょうか。そして、結果４６億円にもなった黒字、繰越金、この要因を区は何と考えているのか伺います。","respondent":"秋山財政課長","answer":"例えば平成２８年度の当初予算であれば、基金からの繰入金を１０３億円ということで、基金からの繰入金を入れて予算を成立させて事業をしています。最終補正でも取崩しを９３億円というふうに計上しておりますので、一方で余裕のある分は積み立てている、そういうものです。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"基金の積増しを重ねていくよりも、目の前の喫緊の課題に対処すべきだと私は思います。１人の待機児も生まないような緊急対策への、それをはじめとした喫緊の住民要求実現のために予算を組むべきだと思いますけれども、いかがか尋ねました。","respondent":"秋山財政課長","answer":"金額にして約７４％増という形で金額を積んでおります。このように、品川区としても十分対応をさせていただいているところです。","id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最初の３つ、なぜそこに聖路加産科クリニック、どのような理由でその聖路加産科クリニックが選ばれているのでしょうか。都立広尾病院とか日赤医療センターのほうがはるかに多いと思うのですが、まずその３点についてお尋ねしたいと思います。","respondent":"太田品川保健センター所長","answer":"ベッド数がかなり多くかつ区民の利用実績があり、ハイリスクも対応してくださるという回答により、聖路加産科クリニックを選定しました。空きベッドが少なく、心配な方がいても、産後ケアの利用はできないというふうに伺っております。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の所長のご返答で、あえて医療機関の必要がなくて、助産師が十分確保できる施設で適当に選ばれたのがこの４つだということが理解されました。まずそこそこ利用者があったとしますと、この事業の中で、例えば区の職員とかネウボラの担当者はどのような形で関わられているのか尋ねました。","respondent":"太田品川保健センター所長","answer":"十分に対応可能であるというふうには伺っておりますが、聖路加産科クリニックが助産院ということで、少し検討しなければいけないと考えています。それから、もちろん必要な場合は、保健師がフォローするという体制をとっております。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"定期接種となった１０月以降のＢ型ワクチンの接種率と、接種数の推移はいかがでしょうか。平成２８年、我が会派の沢田委員が質問した平成２８年３月までに生まれた児が任意接種、トラブル等の報告などはあったのか尋ねました。","respondent":"舟木保健予防課長","answer":"区では任意接種の助成を今年度につきましては継続実施したことで、移行時の対応については特に問題なく、トラブル等の報告はありませんでした。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、水疱瘡ワクチンについてお伺いいたします。水疱瘡は全国レベルで大体年間１００万人患者が発病すると言われておりましたが、この２年間、ワクチンの接種率について簡単に、示すよう求めました。","respondent":"舟木保健予防課長","answer":"１万件前後だったものが、２０１５年には６,７６５件、区におきましても２００件前後だったものが１２６件となっております。平成２６年度は７割くらい、平成２７年度は始まった年で１００％で、今年度につきましても大体９９％前後になるのではないかと考えています。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"意見","question":"定期接種になることによって、Ｂ型肝炎ワクチンも水疱瘡（水痘）ワクチンも接種率が非常に上がって、子どもを守るために非常に有意義だったと非常に感謝しているのですが、Ｂ型肝炎も水疱瘡も良かったですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"塚本委員","kind":"質問・要望","question":"私から、５２ページのリサイクル資源売払収入と、関連して６６ページのリサイクル推進費に関してまず質問をさせてほしいと求めました。","respondent":"小林品川区清掃事務所長","answer":"こちらは同様に単価が３３.８％減になっておる関係で、２,０００万円強の減収ということで、その合計がご指摘の金額です。申し訳ございませんが、収入を十分確保できなかった関係で、結果的に一般財源をもって同額を経費補填していただきたいと考えております。","id":"exchange-078"},{"speaker":"塚本委員","kind":"意見","question":"今、５００万円弱の減収ということで７％減もかなり大きな要因ですが、今ぐらいの価格というのが今後もずっと続くというふうに見ておられるのか。単価というものによって左右される収入ではありますけれども、今後の見通しについてどのように考えておられるのか説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"大体今ぐらいのkg当たり８０円から１００円ぐらいの単価でアルミは推移するものと考えておりまして、来年度、確保できると考えております。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問・要望","question":"昨年ぐらいまでと言ったほうがいいのでしょうか、ある意味、売払収入が大体全体の１割ぐらいを占めているのでしょうか。市況に応じた新たな改善の余地というのですか、そういったところで何かお考えがあるかお聞かせをほしいと求めました。","respondent":"小林品川区清掃事務所長","answer":"資源回収は、行政回収と集団回収、拠点回収の三本柱の構成になっておりまして、その役割分担と効率化がポイントになるかと思います。あるいは３つの回収の役割分担を考えて、来年度以降、対応してまいりたいと考えております。","id":"exchange-080"},{"speaker":"塚本委員","kind":"意見","question":"政策というか、そういったこともぜひお願いしたいというふうに思いますので、よろしくお願いしたいと思います。７３ページの橋梁長寿命化修繕経費についてなのですが、そういうものがわかるような、どのように考えていらっしゃるかお願いしますとの意見を述べました。","respondent":"多並道路課長","answer":"ホームページでも公表していますが、または長寿命化することで全体的にこれだけプラスになっていくということを示させていただいているところです。いきなり壊れて直すということではなくて、それを１つ１つ延ばしていくというのが考え方ですので、１つ１つ考えるものです。","id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"２０２０年のオリンピック・パラリンピックに向け、なぜこの時期に国庫支出金が、１４１万円余のマイナスになった理由をお聞かせください。マイナスの影響はどこに出てくるのかも、わかれば教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"理由といたしましては、諸収入で９２６万円が入るため国庫支出金の減と一般財源の減ということになっているものです。この影響についてですけれども、５３ページと４１ページに、財源について載っておりますので、そちらのほうも見ていただければと思います。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問・要望","question":"５９ページに諸収入増額に伴い更正減額とありますけれども、補正前の額に合わせるために一般財源をカットしたということでよろしいのかどうか教えてほしいと求めました。","respondent":"秋山財政課長","answer":"これは一般財源のほうが、諸収入がプラスになりましたので、その分、一般財源が７８４万６,０００円使わなくて済むのだという、そういう意味です。","id":"exchange-083"},{"speaker":"木村委員","kind":"意見","question":"先ほど、スポーツ振興くじにより諸収入として９２６万円が付くとの答弁がありました。これは、スポーツ振興くじの中でも、どういう部分に当たるのか説明を求めました。","respondent":"池田スポーツ推進課長","answer":"９２６万円付いているのは、他にスポーツ振興くじということで助成金をいただいているものとして、他にも学校の校庭の人工芝化ということでいただいているものも２カ所ほどあります。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問・要望","question":"それとも何をどうすれば配当金が入ってくるのかということもお聞かせください。競馬組合配当金や宝くじなどもそれに当たるのかと思うのですけれども、間違っていたら、教えてほしいと求めました。","respondent":"品川庶務課長","answer":"それから平成２５年度には付いていないというような状況で、毎年付いたり付かなかったりというような状況があります。ｔｏｔｏのほうで、申請してくる自治体等の数によってもこの助成金等の出方が変わってくるのかと、このように思っております。","id":"exchange-085"},{"speaker":"木村委員","kind":"意見","question":"諸収入の中に、先ほど競馬組合の配当金や宝くじもそれに当たるのかどうかということもお答えくださいとの意見を述べました。","respondent":"秋山財政課長","answer":"これは補正予算ですので、年度の中でそういう新たに宝くじ等からお金が入ってきたときには、その諸収入というところで受けている、そういうものです。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"今回の９２６万円ですけれども、平成２７年度などにも入ってきたということでありますけれども、他にはどういうことに使うのかということもわかれば説明を求めました。","respondent":"秋山財政課長","answer":"先ほど庶務課長からもお話しさせていただいたように、あちら側で品川区からの申請について出しますというものを計上していると、そういう形です。","id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"５８ページの文化スポーツ振興費の欄ですけれども、補正額が０になっています。この一般財源マイナス７８４万円余は、何がマイナスになったのかということを説明を求めました。","respondent":"秋山財政課長","answer":"国庫支出金を予定していましたが、それからもう１つ、差額として７８４万円が一般財源を使わなくて済んだです。特段、何に使ったということではなく、諸収入を充当した事業に一般財源として使わなくなったというふうにご理解いただければと思います。","id":"exchange-088"},{"speaker":"木村委員","kind":"意見","question":"最後に１つだけ、７７ページの不燃化１０年プロジェクトがありますけれども、なぜ１０年プロジェクトとなっているのかお聞かせください。つまり、なぜ１０年という年数としたのか、理由を説明を求めました。","respondent":"寺嶋木密整備推進課長","answer":"「『２０２０年の東京を支える』１２のプロジェクト」ということで、２０２０年を目途に強い都市をつくるということでつくり上げた事業です。その中の１つの木密地域不燃化１０年プロジェクトという施策を２３区が実施している、こういった経緯です。","id":"exchange-089"},{"speaker":"渡部委員","kind":"確認","question":"８６ページですとか、９６ページにも記載があるのですけれども、少しマイナンバーの関係について様々議論させていただければ、伺えればと思います。だから、この９２６万円は、あくまでも中延小学校の照明だけの金額だったのかというところ、先にそこだけ確認させてください。","respondent":"秋山財政課長","answer":"ここの９２６万円は中延小のものです。","id":"exchange-090"},{"speaker":"渡部委員","kind":"確認","question":"先ほどの議論の中で少々ごっちゃになってしまっていたので、そこだけ確認させていただいて、マイナンバーの後で聞きます。引き続き行うというのですけれども、今後のスケジュールを教えてほしいのと、なぜそのようにもう１回延長になるのか。","respondent":"提坂戸籍住民課長","answer":"そちらのほうを戸籍住民課の事務室に移しまして、５月の連休明けからは、戸籍住民課の事務室のほうでマイナンバーカードの交付を行ってまいります。防災センターの３階につきましては、連休明けから原状回復工事を行う予定です。","id":"exchange-091"},{"speaker":"渡部委員","kind":"質問","question":"このカード普及率といいましょうか、カードの普及率は、今年度はどうだったのでしょうか。どういう聞き方をしたらいいか尋ねました。","respondent":"提坂戸籍住民課長","answer":"既に２月末までにマイナンバーカードを交付した方が４万７４１件です。３月末の段階で大体４万３,０００件程度の方にマイナンバーカードを交付したいという考えです。","id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"少ないなと思うのですが、そもそも国なり区なりが見立てた想定があったと思うのですけれども、それと比較してどうなのでしょうか。その辺の感覚がわかれば説明を求めました。","respondent":"提坂戸籍住民課長","answer":"平成２７年度と平成２８年度合わせて２,０００万件を見込んでおったのですが、今年度末で国全体の見込みが１,０００万件余です。それと比較しますと、品川区の交付率は上回っているという状況です。","id":"exchange-093"},{"speaker":"渡部委員","kind":"質問・要望","question":"使いこなせる人しかできないですから、写真を撮るなりして手続きはできるのだけれども、そうでない人は多分置きっぱなし。現実問題として伺うのですけれども、例えば私のせがれですと、学校に提出しなければいけない書類とかで番号を記入しました。","respondent":"提坂戸籍住民課長","answer":"ご本人が窓口に来ていただいて個人番号入りの住民票をお取りになって、その上でその番号を勤務先に提出していただければ、用は足りるということになっております。","id":"exchange-094"},{"speaker":"渡部委員","kind":"質問","question":"ただやはり基金は大事ですよ、ないと困ったときに大変ですからね。実際、この半年近くやってみて、コンビニ交付はどれぐらいになるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"コンビニ交付の交付件数ですけれども、２月の末で住民票が１,７４２件、印鑑証明は９７０件となっております。これをさらに伸ばすようＰＲを続けてまいりたいと考えております。","id":"exchange-095"},{"speaker":"渡部委員","kind":"質問・要望","question":"後ほど現時点での実際の申請状況がどれぐらいなのかということもあわせて伺いたいのですが、通知カードからの切替えはお済みですかとか、ポスター。場合によっては国の仕事かもしれないのですが、何かこれからこういうふうに取り組んでいくというようなものがあれば、教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"１カ月、２カ月ごとに周知をしまして、普及を進めてまいりたいと思います。あわせて、町会の掲示板にポスターなどにも張らせていただき周知を行う予定です。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほど、地域スポーツの５８ページの金額のところは伺いました。区内での、登録団体と言っていいのでしょうか、いわゆる学校を使って活動している団体数。","respondent":"池田スポーツ推進課長","answer":"当初百数十だったものが、そこから２０団体も増えているような状況でございまして、今後も増えていくというようなことは見込まれているところです。","id":"exchange-097"},{"speaker":"渡部委員","kind":"質問・要望","question":"場合によっては余裕教室の活用というのでしょうか、様々な部分で、その辺はお金が様々なところから入ってくるものがあるのでしょうか。最後に一言だけお願いします。","respondent":"池田スポーツ推進課長","answer":"今のご指摘につきましては、今後も機を見て、いただけるものはいただくような形で申請をさせていただきまして、区民の皆様のスポーツを振興するように努力していきたいと考えています。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"３６ページの特別区民税、様々絡めまして、６４ページの児童福祉費についてお聞きします。それから減少に転じる時期をどのぐらいと考えているのか、まずお聞きします。","respondent":"秋山財政課長、黒田税務課長、大澤待機児童対策担当課長","answer":"補正の考え方というか、ポイントですけれども、まず１つは、歳入面では特別区税、住民税の伸びがあったということ。年度内の国庫支出金等であれば… ０.４８ポイントほど就業率が上回っておりますので、この１０億円ぐらいは確保できるだろうということで補正予算を編成しています。… 区の乳幼児人口のピークは、平成３３年以降と見込んでおります。","id":"exchange-099"},{"speaker":"西本委員","kind":"意見","question":"それらを解消していくという中で、どういう比率で全体を考えていくのかというところがもしもお考えがあればお願いしたいと思います。それをどういうバランス、やはり今から考えて政策に取り入れていく必要があるかと思うのですが、その辺の考えがあれば説明を求めました。","respondent":"柏原企画調整課長、大澤待機児童対策担当課長","answer":"１０年前と比べて、今は安定したといいますか、割合としては若干ですけれども増えている状況があります。人口動向などを見ながら、施策、予算は今後も考えていきたいと思ってあります。 今、保育需要が落ちてきたときには、事業者は柔軟に対応できるというふうに考えております。例えば平成５５年以降ですとか、そのときに利用者に混乱がないようにスムーズに閉園できるように支援していくのが区の役割と認識しております。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区として、公立になりますけれども、その公立についてはどういうふうに考えていくのでしょうか。ただ単に経費の削減という形でそれを決めるということではなくて、やはり全体的な流れの中で考えてほしいと求めましたが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"保育の需要と供給に関しましては、子ども・子育て会議の中でも十分に議論いただきまして検討していきたいと思います。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、まず４３ページのいじめ防止対策費、２点目が、１１０ページの高額医療費共同事業交付金、この２点でお伺いしたいと思います。１１１ページ、８０万円を超える高額な医療費が使われた件数と、主な病気治療がわかれば参考までに説明を求めました。","respondent":"村尾教育総合支援センター長、高森国保医療年金課長","answer":"ただ、警察ＯＢにもＨＥＡＲＴＳの一員として様々な学校の対応に努めていけるということで、特に影響等はないというふうに考えているところです。特に教育委員会の責務というところで、いじめ防止に対する必要な措置を講じる… ３５０件程度となっておりまして、平成２８年度の見込みですと、４,２００件程度かと考えております。糖尿病等によります人工透析の入院または通院、それと新生物ということで、がんというふうな形になるです。","id":"exchange-102"},{"speaker":"こんの委員","kind":"質問・要望","question":"私が言うまでもありませんが、意識を持ってこの点については取り組み続けていただきたい、このように思います。人間ドックの助成制度をしましたが、この助成を始めて、高額療養費にどんな効果が出てきたのかということを説明を求めました。","respondent":"高森国保医療年金課長","answer":"病気を発見させていただければ、合併症等が出ないようなコントロールもできるようなことでございまして、結果として医療費が抑えられるのではないかというふうに考えているところです。","id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"もっと人間ドックを進めていただきたいのと同時に、もう１つ、脳ドックというのも大変に有効だというふうに思います。かねてから区議会公明党としては、このことを先輩方が上げてきた声でもありますけれども、その点、脳ドックの必要性はどのように考えますか尋ねました。","respondent":"高森国保医療年金課長","answer":"こちらは平成２６年度から開始している事業でございまして、１件８,０００円を限度に助成をするというふうな形で事業をスタートしたものです。脳ドック等につきましても、やはり必要性はあるとは考えてありますが、現状では検討課題ということで承っておきたいと思います。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう１つ、こうした出産に関わることで、これは出産をされる方に何かこうしたことで安心感を与えるそうしたお知らせというのはあるのでしょうか。何かこうしたリスクをしょったときに、医療でかかったものはきちんと返りますというようなお知らせはしているのか尋ねました。","respondent":"高森国保医療年金課長","answer":"申し訳ございません。区ではいたしておりませんけれども、医療機関のほうで、そういうふうなことは様々な形でサポートしていただいていると考えているところです。","id":"exchange-105"},{"speaker":"こんの委員","kind":"質問","question":"医療機関では、お知らせするところとしないところとあるので、もし出産のお知らせのパックにそうしたものもお知らせとして加えられるといいかなというふうに考えますけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"関係各課と調整させていただきたいというふうに考えてあります。","id":"exchange-106"},{"speaker":"渡辺委員","kind":"質問・要望","question":"利用者の要望も多くある中で、２０年を見据えた、大きなチャンスだと思います。本日は、今、場所として３つありますが、特に、天王洲のところをまず伺えればと思います。","respondent":"溝口公園課長","answer":"一般的というものがないのですが、通常見ていますと、やはり５年ぐらいでだんだん傷み始めてくるというのが通常です。その部分の補修はしっかりやって、あまりにもひどい場合には最終的には全面改修ということも計画的に考えていきたいと考えているものです。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問・要望","question":"前もちょっと申し上げたのですが、この辺も想定をぜひ整備をしてほしいと求めましたがいかがですかということを、関連して１つ伺っておきます。そういったところでグラウンド面などの整備、考え方を伺いたいのが１つです。","respondent":"溝口公園課長","answer":"今後も様々なニーズに応えられるような、対応できるような施設整備、そういったものを考えていきたい。約１００m2の多目的室を設置いたしますので、今後、検討していきたいと考えているものです。","id":"exchange-108"},{"speaker":"いながわ委員","kind":"質問","question":"簡単にお伺いしたいのですけれども、補助１６３号線整備で、３億８,９００万円ほど減額をされております。差し引くと８億円余になるのですが、工事実績というのですか、その辺がどうなのかということを説明を求めました。","respondent":"多並道路課長、鈴木建築課長、品川庶務課長","answer":"私からは、補助１６３号線についてお答えします。そのうち各年度ごとに行う工事ということで、年度ごとに協定を結んでございまして… 引っ越しができないとか、耐震化に踏み出すこと自体がもう億劫で面倒くさいとか、そういった声も聞かれております。こういったことを踏まえて… 外壁改修の該当する学校名ですが、山中小学校、旗台小学校、冨士見台中学校です。","id":"exchange-109"},{"speaker":"いながわ委員","kind":"質問・要望","question":"地図で確認ができたということだったので、ちなみに、減額をしたこの３億８,９００万円余というのはどこに行ってしまうのか。これは小学校の１校なのか２校なのか、それとも小中合わせて３校分が何となく全体的に減額されたものなのか、もしその理由がわかれば説明を求めました。","respondent":"多並道路課長、鈴木建築課長、品川庶務課長","answer":"平成２９年度に、工事の終わりは平成３１年度で変わらないと言うことですので、圧縮するようなことでやっていこうと考えているものです。例えば採光ですとか、そういったところは問わない等の対応はさせていただいているところですので、できるだけ柔軟に進めてまいりたいと考えています。設計の段階で外壁の塗装にアスベストが含まれていたということで、今年度、工事は取り止めております。","id":"exchange-110"},{"speaker":"南委員","kind":"質問","question":"そして、６期の最終年の平成２９年度の基金残高は６億３,０００万円というふうに説明してきました。各年度の取り崩した額、そして平成２９年度末の見込額は幾らか、まず説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"予算では６,５７０万８,０００円となっており、出納閉鎖である５月の決算のときにその金額が確定してくるものになっております。最終補正予算書に記載のとおり、平成２８年度末の見込額が、１７億７,５７４万５,０００円という見込みになっております。","id":"exchange-111"},{"speaker":"南委員","kind":"質問","question":"平成２８年だけで１億１,０００万円、それにプラスして平成２９年はここの資料に出ておりますけれども、どのように評価をしているのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"見込みに比べると、取崩しの金額は少ないという状況になっております。ケアマネジメント自体の方法については、区としては変わりありませんので、そこが主な要因だというふうに考えております。","id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"当初、６億３,０００万円の基金残高としていたものが、平成２９年度末では、この資料によりますと、１５億３,０００万円となっているわけです。先ほど質問しましたように、これだけ品川区の介護保険財政、豊かな財政があるというふうに見ていいのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"毎期減っているところです。高齢者の人口がかなり増えることが見込まれること、どういう見込みになるかは予想がつきませんので、このぐらいあって。","id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"６億３,０００万円というふうに残高を予想した結果、どのように区としては見ているのかというふうに、改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第６期も基金から充当して保険料を安くしていますけれども、この先、区としてもこれは問題だというふうな意識を持っていたところです。ただ、現実として国の制度の変更があったために、そこを回避できたということは、良かったというふうに評価しています。","id":"exchange-114"},{"speaker":"南委員","kind":"意見","question":"そのような指導をしていたわけでありますけれども、訪問型サービスＡでは、品川区の介護報酬は１５％も引下げをしているわけです。品川区としては、こういう介護報酬の引下げ、これについてはどういうふうに現場の実態を見たり聞いたりしているのか、その辺の認識をお願いしますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"品川区の方法としては、質の担保ということを一番に考えておりまして、その質の部分を加算ということで独自の加算の制度をつくっております。","id":"exchange-115"},{"speaker":"南委員","kind":"質問","question":"そういうケースは聞いていないということなのですけれども、加算はつけていると言ってもやっている中で、大変だという意見は聞いていないのですか。私はどういう実態になっているのかということを、どう見聞きしているかというふうに聞いたのですけれども、その点についてもう一度答弁してください。","respondent":"永尾高齢者福祉課長","answer":"当初この報酬の単価を説明したときには、当然のことながら、どうやってやっていこうかという相談は多数来ております。それに対しては、１つ１つ回答を文章で書いて返しておりまして、それに対して実際に倒産した事業所は聞いていないということです。","id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"自分の今の生活だけではなく、数カ月以上にわたって大変な状況になるわけですから、倒産などさせるわけにはいかないではありませんか。もう時間もないので答弁はいいのですけれども、やはりきちんとした守る姿勢で支援をしていただきたいということを要求しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ある程度これをつくるときから３カ月の予想を立てているわけでしょうから、その３カ月間の中で、そこら辺のところをまず初めにお聞きしたいと。そういうこともあると思うので、そういう形の全体像をどういうふうに捉えて、この最終補正が出てきているかということを教えていただきたい。","respondent":"秋山財政課長","answer":"現時点で進行がどうなっているかということをしっかりと認識した上で、補正をするかしないかという形になってくるのかなというふうに思ってあります。これとこれとこれに該当すれば最終補正で、そうでなければ決算対応だとかというようなことは、なかなかこれはやりづらい。","id":"exchange-118"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"平成２７年度決算時が９０３億円、その前のこの最終補正が８４５億円だったものが、出納閉鎖が終わった後の決算で約６０億円増えたわけです。６０億円だと変わってきてしまうと、そこら辺の数字をどう捉えているのかということと、そこら辺はどうお考えかということを教えていただきたい。","respondent":"秋山財政課長","answer":"平成２８年度の最終につきましても、９０億円強を積み増しているということで、若干基金の増え方は去年に比べるとかなり減っているという状況です。平成２７年度の最終での伸びというのは、有効に使って、事業を充実させていきたいというふうに考えているものです。","id":"exchange-119"},{"speaker":"石田（秀）委員","kind":"提案","question":"２点目は、９時で、私は１１時にすることを提案したい。議長会なりから意見を言って、そういう活用をしていくべきだと考えていますが、そこら辺についての考えを説明を求めました。","respondent":"秋山財政課長、久保田総務課長","answer":"最終補正の精度です。基金とか積立ての時に区民にわかりやすい説明も同時に必要だと思っていますので、今後とも精度を上げてわかりやすい説明をしていきたいと思います。こうした意味からも、様々な事業等で活用できるようＰＲに努めながら、また競馬組合とも連携して進めていきたいと思ってあります。","id":"exchange-120"},{"speaker":"石田（秀）委員","kind":"提案","question":"我々ももちろん提案をしますけれども、一緒になって行政とやっていかなければ、ここの部分は区民参加型ができないと考えています。ぜひそこら辺をお考えいただいて、我々も提案していきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"７３ページの下水道合流改善事業、それから５０ページの基金繰入金関係の２点をお伺いしたいと思います。それからもう１点は、補正予算書の８７ページに、これについてもう少し詳しくご説明をほしいと求めました。","respondent":"和田河川下水道課長","answer":"今年度中に工事の大部分を終了いたしまして、来年度、今年の６月ぐらいまでには工事全体が完了する見込みです。８７ページの設計変更等に時間を要しという具体的な内容ですけれども、これの協議、検討等に時間を要したものです。","id":"exchange-122"},{"speaker":"若林委員","kind":"確認","question":"今年の６月で、その２が完了するという意味ですか。債務負担行為でその３というのも見えるのですが、そこも確認させてください。","respondent":"和田河川下水道課長","answer":"その３ですが、水神公園のところに、この貯留施設用の空気抜き設備をつくる予定です。そういう意味では、６月までには全ての工事は完了し、この勝島運河の貯留施設の工事全体が完了するという見込みです。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"なぜ目黒川と立会川でＢＯＤの環境基準が違うのか、これは環境課長になるのでしょうか、お聞かせほしいと求めました。これまでずっと要望しております東京都に対して、区長を先頭に要望しておりますけれども、動きをお聞かせいただきたい。","respondent":"和田河川下水道課長","answer":"答弁が前後しますけれども、合流改善の都の姿勢ですが、目黒川につきましては、これまでに平成２４年と平成２６年に合流改善施設をつくってあります。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"５年と言わず、これは進めていただきたいというふうに要望しますので、よろしくお願いします。これは何か意味があるのかいうことを、３点お聞きします。","respondent":"秋山財政課長","answer":"実質収支というのが平成２７年度から平成２８年度に繰り越す金額そのものですので、合わせているということです。こちらのほうは減額をして、今回、繰入れをゼロという形にさせていただいているものです。","id":"exchange-125"},{"speaker":"あべ委員","kind":"確認","question":"６５ページの認可保育所移行支援について、それから８４ページの午前中も少し質問がありました給与費の明細についてお伺いしたいと思います。例えば月１００時間以上、国のほうでも議論されている月８０時間以上の残業があったのかどうか、月当たり人数を教えてほしいと求めました。","respondent":"秋山財政課長、大澤待機児童対策担当課長、米田人事課長","answer":"土木費の補助金で、歳出の減により結果としての国費の減となり歳入減という両方あるというふうに、この段階ではお話しさせていただきたいと思います。認可保育園への移行ですけれども、移行したいという園はあったのですけれども、認可の要件に合わなくて見合わせたという経緯があります。… ８０時間がいわゆるかなり厳しいラインだと思いますが、それを超えている職員も若干はいるというようなことで、現状、つかんでおります。","id":"exchange-126"},{"speaker":"あべ委員","kind":"確認","question":"年度途中でも希望が出てくれば、それは予算も込みで対応するという姿勢はあるのかどうか、確認をさせてください。１人の人が数カ月ということでも、あるいは複数の方がということでも、もしこうした残業の多い職場があれば説明を求めました。","respondent":"秋山財政課長、大澤待機児童対策担当課長、米田人事課長","answer":"全体のトータルの金額は国としても確認をしていますので、この国費の減による事業の減は特に再開発の場合はありません。… 認可保育園の移行ですけれども、今後、認可へのご希望があって、要件を満たすことができましたら、それは今後とも支援をしてまいります。 高齢者地域支援関係、それから、そういうようなところが超勤時数の高い職員が存在するとしてリストアップされているものです。 答弁漏れがありました。事業が滞っているかですけれども、再開発についてはそういうことはございません。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問","question":"今、ここを例えば暫定拡幅をすることによって渋滞を一定解消することは考えられないだろうか、その１点だけお伺いできればと思います。現場の努力だけではちょっと難しいのではないかと思うのですが、人事のほうでも、所管のほうでもお話を伺えればと思います。","respondent":"稲田都市開発課長、米田人事課長","answer":"建物完成なのですが、平成３０年１月に事務所棟、平成３０年８月に住宅棟ということで、建物の完成予定は進捗どおり行っているです。地域の方にもご理解いただきながらやっていきたいと考えております。 人員については、所要人員ということで、毎年度、職場の状況も見据えながら増減を図っているところです。そういうような対応も１つですし、引き続き、強力に進めてまいりたいと考えています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"このような背景の中で平成２８年度が始まったわけですが、今回の減額補正については、確保すべき人数が集まらなかったのでしょうか。全体の給与の単価が下がったのか、この２億円および３,４００万円のところについてご説明をほしいと求めました。","respondent":"米田人事課長","answer":"一方、平成２８年度の１２月の定点で見ますと、８２７人ということで、それとの相差は５名ということで、５名マイナスということになってあります。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"就学前の乳児教育のほうの幼稚園の先生方のものは、今お話しあったこの中に入っているとのことですが、教育費のほうではないか尋ねました。","respondent":"米田人事課長","answer":"単独の幼稚園と、それから幼保一体施設ということで、教育のほうは単独の幼稚園について計上しています。一体施設については、こちらのほうに計上しておりまして、こちらは現員でやっておりますので、それが欠員であるということはございません。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"かなり様々なご努力をされたと思うのですが、それでも足りない状態とかが生じていたのでしょうか。その辺をお願いしたいと思います。","respondent":"米田人事課長","answer":"４月１日の採用ということで、それについては年度途中の欠けた分等も含めて、４月１日で採用していくです。育休については任期付き職員を、それから退職については派遣職員等をあてがえるといった補充の努力をしています。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"広い範囲で、やはりオール東京、２３区で確保できるような方法を何とか考えていくことはできないでしょうか。品川区が先頭で各区で働きかけていくようなことはできないのか尋ねました。","respondent":"佐藤保育課長","answer":"広域的な保育士の確保策ですが、平成２７年度から国の公定価格での上乗せ、また東京都の独自事業でありますキャリアアップというところで保育士の確保と、ある程度、広域的なバランスのとれた処遇改善政策を進めているところです。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"８２ページですが、１目の元金のほうだけでお尋ねしますけれども、利子と違って確定をしているのだと思います。素人ですので思い当たるのは繰上げ償還ぐらいしかないのですが、わかりやすくお話ししてほしいと求めました。","respondent":"秋山財政課長","answer":"今回の公債費の補正ですけれども、これは平成１７年、平成１８年の減税補てん債についての利率の変更というものです。今回、元金が増えまして利子が減るという、そういう関係になっているものです。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問","question":"品川区にはそのうち３億７,６５５万円が入っていますけれども、この５節にこの部分が入ってくるのか伺いたいですが、どこに入るのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"３億７,０００万余の国からの保険者支援金ですが、１項国庫負担金、国庫分が含まれてあります。年度当初に８％程度を見込んで、その枠の中で調整しておりますため、この補正予算の中には含まれてございません。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"この報奨金について、代表質問でもさせていただいたのですが、平成２７年度の報奨金は９,３００万円という答弁でした。この９,３００万円の内訳を説明を求めました。","respondent":"高森国保医療年金課長","answer":"滞納処分部門で差押件数による交付が３,０００万円、差押割合による交付が３００万円ということで、合計９,３００万円です。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、収納繰越分の収納率が何％で、その伸び率が何％か。そして、差押件数がどれくらいかという、この実績の内訳もお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"ご説明をします。差押割合による交付ですが、４.２７％でございまして、東京都のほうでは３％を達成した場合に３００万円です。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問","question":"この品川区の国保収納率は、２３区で２位でありますが、その背景には、苛酷な取り立てがあることを代表質問でも述べてきました。最低生活費は差し押さえてはいけないとなっていますけれども、この最低生活費が幾らか認識はされているでしょうか、伺います。","respondent":"高森国保医療年金課長","answer":"給与の場合の差し押さえによっては、基本的には１人１０万円プラス生活、体面維持費ということで２割程度というふうな形になります。扶養者が１名いますと、プラス４万５,０００円ということで認識しています。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問","question":"最低でも１４万５,０００円は残しておくと、そういうことがわかっているのに、口座に入れば全て差し押さえるのはなぜなのか伺いたいと思います。とても個々の状況により対応をしていると言えないと思うのですけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"預金に入ったお金につきましては預金債権という認識で対応しておりますが、個々の案件に基づいて様々な状況があります。こういう方については、納付いただくようにお話を申し上げ、場合によっては全額取り立てをして保険料のほうに充当している状況もあります。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは前回も質問のところで示させていただいているところですけれども、払うことを諦めさせているというのが今の区の実態なのではないでしょうか。それらを使って、高過ぎる国保料の引き下げ、そして払える国保料にしていくべきだと思いますけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"３億７,０００万円余につきましては、これは軽減等を行っている保険者に対しての保険者支援金という性質で公費が入ってきてあります。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり国保の根本になるのは、区民の健康と命を守るという、そしてそこにしっかりと払える保険料にしていくことではないでしょうか。通知だけで、そのまま何もなければ差し押さえる、これが容赦のない差し押さえでないと言えるのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"申し上げているとおり、個々のケースに基づいて、中には収入が少ない方でも、４年も５年も一切払っていないというふうな状況の方もいらっしゃいます。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは違法だと、区は違法ではないというふうにおっしゃいますけれども、違法な取り立てだと私は思います。しっかりと国保が払える国保料にしていくためにも公費の投入をしていくべきだと思いますけれども、改めていかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"繰り返しになりますが、様々な形でご相談いただきたいです。","id":"exchange-141"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、補助金、助成金全般についてお伺いしたいのと、４６ページの教育費委託金についてお伺いします。こういった補助金がありますけれどもというような紹介型というのですか、改めて教えていただきたいのと、まず説明を求めました。","respondent":"秋山財政課長","answer":"それを積極的に申請をするという、どちらかというと、大きく分けるとその２つがあろうかというふうに思ってあります。それ以外の外郭の財団等がありますので、情報を取りに行って、使えるものは全て使うというつもりでやっているところです。","id":"exchange-142"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"どういう対応をとっていくのか、ここは１回見送ろうというような、区のお考えをお聞かせいただきたい。今回この最終補正で、どれがそういった区のテクニックを駆使して獲得をされたのか、もしあるのであれば教えていただければなと思います。","respondent":"秋山財政課長","answer":"１つ目のご質問ですけれども、その事業をそもそもやる意味があるのかというところに立ち戻って考えるべきとだというふうに思っています。３年間ですけれども、総額で２,４００万円つくということで、これを取ったです。","id":"exchange-143"},{"speaker":"石田（し）委員","kind":"質問","question":"時間がないので次へ行きます。５０万円から２０万円に減額がなされた中で、事業間流用であればそれで構わないのですが、その点を改めて説明を求めました。","respondent":"熊谷指導課長","answer":"オリンピック・パラリンピック教育の推進事業でありますけれども、各学校そして幼稚園に３０万円ずつついているものです。ですので、それを活用して行ったです。","id":"exchange-144"},{"speaker":"石田（し）委員","kind":"質問","question":"ということは、この委託金は、学校を指定はされていなかったのか、それともオリンピック・パラリンピックの関連予算の指定されている学校だから、要は同時に合わせてできたということなのか、そこを改めて説明を求めました。","respondent":"熊谷指導課長","answer":"３０万円をオリンピック・パラリンピック教育の予算として受けつつ、伝統文化ということで２０万円上乗せして５０万円の予算があります。清水台小学校、荏原第一中学校が、オリンピック・パラリンピックの中で行ったです。","id":"exchange-145"},{"speaker":"石田（し）委員","kind":"質問","question":"当初の予算を組み立てたときと比較して、半減ですので、正直、事業の内容が大きく変わってしまうのではないかと。その点、当初予算のときと今回の最終補正で変わったことはないということを最後に一言いただければと思うのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"そもそもこの事業ですけれども、平成２７年度のときは、伝統文化を学ぶ授業でございましたが、平成２８年度は発信ということで、午前中にもお話しした都立学校に派遣されているＪＥＴ青年との交流が主です。","id":"exchange-146"},{"speaker":"たけうち委員","kind":"質問","question":"それから２点目の各種がん検診は、この２,３９０万２,０００円というのは、乳がん検診の分の追加分ということでいいのかどうか。特定緊急輸送道路が１３棟というのが予算書だったのですが、このうちのどれがどのように減ったのかということがわかれば説明を求めました。","respondent":"廣田子ども家庭支援課長、川島健康課長、鈴木建築課長","answer":"もう１つが、冬場については、インフルエンザ等の感染症が増えるということで、その点を勘案した予算立てはしております。… 今、こちらは乳がん検診の実績が伸びておりまして、約２,０００件ほど受診が伸びるということで補正予算を組ませていただきました。… 耐震化事業についてのご質問ですが、委員ご説明いただいたように、耐震化事業の中身、診断、設計、補強工事、除却費助成と様々なメニューがあります。","id":"exchange-147"},{"speaker":"たけうち委員","kind":"提案","question":"それからこの間、この１年で結構なのですけれども、区のほうで乳がん検診の受診体制の何か拡充があったのかどうかもわかれば教えてください。ただ、１棟当たりの予定されている補助額が大きいから減になったのかなと思うのですけれども、その辺のところをもう一度説明を求めました。","respondent":"廣田子ども家庭支援課長、川島健康課長、鈴木建築課長","answer":"医療費についてですけれども、所得制限を設けていない関係で、人数が増えてしまえば医療費は自ずと増えてしまうという状況にあります。今後… ２,０００件というのは、ほぼ２,０００件ということと同義ということで、説明は２,０００人ということでします。… 実績的には件数はほぼ想定に達しているのですけれども、１件当たり助成した金額が小さかったということで、その分の補正額が非常に大きいと。","id":"exchange-148"},{"speaker":"たけうち委員","kind":"提案","question":"前にご提案させていただきましたが、簡単にはいかないと思いますけれども、よろしくお願いします。これは非常に大事な施策なので、様々な効果的なやり方をまた検討してほしいと求めましたので、要望して終わりにいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-149"},{"speaker":"松澤委員","kind":"質問・要望","question":"７５ページ、それと７７ページ、都市防災まちづくり事業費更正減額についてお聞きしたいと思います。パルム駅前地区再開発事業、駅前通り地区再開発事業と５つありますけれども、これらの完成年度と現状の進捗状況をお知らせほしいと求めました。","respondent":"稲田都市開発課長","answer":"現在、掘削工事をやっておりまして、竣工予定が平成３２年を予定しております。それから、武蔵小山駅前通り地区ですが平成３３年２月を予定しております。","id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"昨年度が９億円強、今年度は４７億２,９１６万円、特に今年度大きくなっているのです。なぜ今年度だけこんなに増えてしまったのかということをお聞きしたいと思います。","respondent":"稲田都市開発課長","answer":"再開発事業ですが、その地区、今、６地区ほど事業中ということでやっております。国の配分の減がございまして、その大きいものに対して国費の配分が減となったものですから、非常に大きな額の違いが出ているです。","id":"exchange-151"},{"speaker":"松澤委員","kind":"確認","question":"今の西品川は、補助金が減になったというふうに聞こえたのですが、そうなのですか。もう一度確認しておきたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中で、補助金の配分の違いがあったりしますので、各年度ごとで修正をかけながら事業計画を見直しながらやっていっているです。多少の違いはありますけれども、トータル的には、事業をやっていけるというところでやっております。","id":"exchange-152"},{"speaker":"松澤委員","kind":"質問","question":"例えば大井一丁目南第１地区再開発事業においては、繰越明許費でしょうか、これがやはり駅前通りにも書いてありますね。西品川一丁目地区では、執行が見込めないから繰り越すという形の繰越明許を使わないで、減だからそのまま残してしまったということなのか尋ねました。","respondent":"稲田都市開発課長","answer":"国の補助の交付年度の変更に伴いまして、年度内に執行が見込めないもので翌年度に繰り越すというところで、追加交付があったです。権利変換計画で補償費等を見込んでおったのですけれども、来年度新たに計画を見直してというところだったのですが、そのようにやっているものです。","id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"４７億余の更正減額が、それは補助金がついていたのが４７億余減額に、そのときにもう補助金がつかなくなってしまうのですか。それとも今年度ついている補助金は、来年度に再計上しても補助金はついて回るということなのか尋ねました。","respondent":"稲田都市開発課長","answer":"今年度の補助金の額、来年度におきましては、また概算要望を出していくです。来年度の要望は少し、全体的に事業をやる中においては、大体バランスがとれているのではないかというところで考えてあります。","id":"exchange-154"},{"speaker":"松澤委員","kind":"質問・要望","question":"もう１つ、大変にこの事業が進んでいるというふうに思われるのですけれども、これは皆さんもう引っ越しをされたということなのでしょうか。その辺のことをお聞きしたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"例えば建物の補償費、見込みで組合のほうから要求があったのですけれども、その分を補正をさせていただいたというのがこの金額の内容になっています。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"公共施設整備基金１０億円、義務教育施設整備基金３０億円、これで６３億円積み上げています。さらに繰越金が当初予算と比べて２１億円増えたということは、単年度で総合計９９億円使わないお金が残ったということでしょうか、説明を求めました。","respondent":"秋山財政課長","answer":"それから財政調整基金の減についてもご説明をさせていただきました。１２月の補正で繰越金を原資に積み立てているというものでございまして、今回の最終補正では特に影響は出ていないというふうに考えております。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"毎年こんなにプラスが残るならば、区民の方は大方減税を望むのではないでしょうか。お金を返すということも、これはやはり考えるべきではないかと思うのですが、その辺についてご見解を説明を求めました。","respondent":"秋山財政課長","answer":"１つは税収が上がっているということで、財政規模ではマイナス２.０％ですけれども、扶助費においては２桁のプラスになっています。民生費等にかなりの額を今回、待機児童も含めて使っておりますので、減税とかということで使うというつもりはございません。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"だから、うちもどんどん２３区を挙げて、良いものを売ればいいじゃないですか。逆にちゃんとやっている自治体にお金が回らない、こういう仕組みはおかしいと思うのですが、何かお考えがあるのか尋ねました。","respondent":"秋山財政課長","answer":"今年２月の区長会総会でも、不公平が生じていることで、区長会でも強く国等に是正を求めているという状態です。ある程度のものは受け皿として用意はするということで、ふるさと納税の仕組みをつくったと、こういうふうな形です。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"これは企画調整課にお聞きしたいのですが、全部満たされているではないですか。どうしてシティプロモーションが必要なのですか考え方を説明を求めました。","respondent":"中島企画部副参事","answer":"シティプロモーションに関しましては、品川区の魅力を区内外に発信するということで取り組んでおります。短期的には様々とご意見もあると思いますが、長期的な人口減少を見据えて取り組んでいるところです。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"現に日本全国を見て、２３区、この品川区などは、人口が非常に増えているのですよ。ところで、このシティプロモーションにテレビＣＭを受注している電通が関わっていると聞いたのですが、これは事実か尋ねました。","respondent":"中島企画部副参事","answer":"今回の平成２８年度、事業を委託しています電通に関しては、電通東日本ということで、１００％子会社に発注をしております。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"１００％子会社に発注しているという話です。そして、滋賀県、京都府、奈良県、和歌山県、このような自治体にも広がっているのですが、品川区はしないのでしょうか、説明を求めました。","respondent":"立川経理課長","answer":"電通ですが、区で契約しているのは、電通の本社ではございません。電通の子会社ということになっておりますので、指名停止ということにはならないということで考えております。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"今ちょっとお話ししたのですが、１００％電通の子会社ということは、それはどう考えてもイコール電通ということではないのですか。それは違いませんか。","respondent":"立川経理課長","answer":"資本がどの程度注入されているということには関わらず、別会社という扱いになっております。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"それで、皆さんの模範となるべき活動、行動をとっているわけではないですか。そして、条例ではどういうふうになっているのか尋ねました。","respondent":"立川経理課長","answer":"いわゆる事業者を指名停止する場合に、区の内規で指名停止基準を設けております。それは国も東京都も設けているところですけれども、区の指名停止基準には抵触しないということで、子会社は指名停止にはしないです。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"それはいつから子会社に変わったのですか。それとも、もともと子会社だったのか尋ねました。","respondent":"中島企画部副参事","answer":"電通東日本に関しましては、プロポーザルで、電通ではなく電通東日本に発注をしています。","id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"それでも全然違う会社だと、そういうふうにおっしゃるわけですか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、３９ページ、シティプロモーション推進経費について伺おうと思っています。この指定寄附金は、そもそもどういうものなのか教えていただきたいのと、この補正が入っている要因というか、内容というか、説明を求めました。","respondent":"中島企画部副参事、伊崎地域活動課長、久保田総務課長","answer":"３９ページのシティプロモーション推進経費の交付金の関係ですが、平成２８年度に、あと動画の制作を行いました。しながわ魅力発信事業」… 東京都のほうから説明会をしていただくということで、町会のほうに説明会のご案内をしたり、周知をしています。 指定寄附金につきましては、寄附をされる方が、これは指定寄附金として年度途中にこういったものがあったということで補正をさせていただいているです。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問・要望","question":"一般質問でもしたのですが、その辺をしっかりとしてほしいと求めましたが、お答えがあればお願いしたいと思います。なかなか活用がされにくいという部分が課題であるのかと思っているのですが、その辺についてのお考えがあれば教えてほしいと求めました。","respondent":"中島企画部副参事、秋山財政課長、伊崎地域活動課長","answer":"鉄道車内の動画広告につきましては、今年度、ＪＲと東急で行いました。動画の再生回数にも大変寄与しておりますので… 今回については職員福利厚生と教育事業指定の寄附がございましたので、補正で載せさせていただいていると、そういうものです。補助金ですけれども、もちろん区でも当然説明会などに行きまして、きちんと理解をして町会長に説明書等を配布し、ご理解いただく努力はしております。","id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"こういうものに使ったらどうですかというアドバイスができれば、２個見つけたので、ご答弁があったらお願いいたします。どういうところが寄附していただいて、団体なのかなと思うのですけれども、その辺の確認をさせてほしいと求めました。","respondent":"秋山財政課長、伊崎地域活動課長","answer":"職員福利厚生指定寄附金は、これは共済企画センターという特別区の職員互助組合の傘下のところからの寄附金です。その団体の性格等も勘案して、こちらのほうで充当事業をここに入れさせていただいた、そういう経緯です。 町会長あるいは町会の会員の皆様に対しましては、地域センターも含めて丁寧に対応していきたいと考えております。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"今、他の委員からも自治体の制度・政策に対する寄附というような形もありますが、ここはそういうものに当たってくるといいなという感じで聞きました。政策の部分でもしっかりと、ぜひとも受け身ではない前向きな積極的なこうした寄附を受けるような取組みもぜひ工夫してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-169"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６ページの歳入と、５７ページの基金積立金の追加、８１ページの義務教育施設整備基金についてお伺いします。合計で４５億円余が潤沢に歳入が増えているということで、福祉増進のために使ってほしいと、これをまず質問します。","respondent":"秋山財政課長","answer":"平成２８年度の決算の見込みですけれども、こちらはまだ見込みなので定かではありませんけれども。５７ページの基金積立金は、こちらについては福祉に使うということでは、なかなかその数字を出すというのは難しいのかと考えています。","id":"exchange-170"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基金のところの差がどれぐらいになるのかということを聞いたので、そこを教えていただきたいのと、財調基金はやはり緊急の対策などにも使えますよね。様々そういう公共施設のところに使えるといった意味では、広く考えて福祉に使える部分がどのくらいあるのか説明を求めました。","respondent":"秋山財政課長","answer":"そういう意味でお話をすると、全部というお答えになろうかと思います。","id":"exchange-171"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして、そこの予算がふさわしく確保されているかどうか、どのように考えているのかお伺いをしたいと思いますが、具体的な中身で聞きます。２３区で最低の福祉というと、多分嫌われる言葉であると思いますが、整備率について、どのような認識を持っているのか、これを伺うのが１点です。","respondent":"中山障害者福祉課長","answer":"特別支援学校の卒業生の卒後の見込み、そうしたものを勘案しながら、足りないところについては整備をするという考え方でいます。現在、平成３１年度に開設されます障害児者総合支援施設の中にも、就労継続支援Ｂ型については２０人ほどの予定をしているところです。","id":"exchange-172"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認識的には遅れていると思っていらっしゃるのか、とにかく障害者福祉全体において遅れている面が多々あるという認識をぜひ全庁的に実感をしてほしい。質問の中で、品川区が障害者の皆さんの今解決してほしい問題を責任持って改善を求めていきたいと思いますが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"実は身体障害者手帳をお持ちの方の約７割は高齢者ということで、就労継続支援Ｂ型というサービスに直に結びつく方が少ないという状況もありますので。","id":"exchange-173"},{"speaker":"飯沼委員","kind":"意見","question":"対策も１つ１つ違ってくると思うのですが、どういう状況にあるのかというのを１つ１つ細かく丁寧に把握するところからスタートすると思うのです。私は、全庁的に障害者の置かれている状況が把握されているのか、共有されているのか、そこをぜひもう１回説明を求めました。","respondent":"中山障害者福祉課長","answer":"そういった意味では、この計画は全庁的に関わる計画ですので、現在の品川区のそうした状況は、全庁的に捉えているものです。どういった支援が必要かというのは、その計画の中で個々のニーズの把握を行い、そのような考え方です。","id":"exchange-174"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改善をする計画に練り直してほしいし、やはり絵にかいた餅にならないためには、この実現のための予算をしっかりとつくらなくてはいけない。この実態から、以上、３会計に反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-175"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、そういうようなことをどうやって具体的に３８万人の区民の方々に対応していくのかと考えていくと、品川区だけでは無理ではないですか。様々な形で国に要望して、３８万人の方々のカード執行には結びつかないと思うのですが、いかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"その方たちになるべく個人番号がどういうものかということをわかりやすく説明するために、今も周知徹底を図っているところです。戸籍住民課だけではなく全庁的に検討して、様々な使い道を広げていきたいと考えています。","id":"exchange-176"},{"speaker":"伊藤委員","kind":"質問","question":"どう言ったらいいのですか、ご本人の承諾をしっかり得た上でないとできないこともあるわけではないですか、非常にプライバシーの高いものであるから。これは２３区だけで抱える問題ではなくて、もっと国に対して要求してもいいのではないですかと思うのですけれども、いかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"２３区の様々な所管課長会ですとか、東京都、国のほうに要望を上げているところです。今後とも様々な問題を話し合って、どんどん国に上げていきたいと考えています。","id":"exchange-177"},{"speaker":"伊藤委員","kind":"質問・要望","question":"本人の確認がないとできない話ではないですか。それから２３区の区長会を含めて、具体的な要望で対応していただきたいと思うのですが、いかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"もっと上のレベルで全国市長会としましても、社会保障・税番号制度における地方自治体支援等に関する提言というのを行っておりまして。品川区もそういう形で一生懸命、周知、ＰＲを行ってまいりたいと考えています。","id":"exchange-178"},{"speaker":"伊藤委員","kind":"質問","question":"だから、そういう観点からも、サイバーパトロール等と連携をしたいじめ対策を新しく構築すべきと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"学校のほうに連絡をし、すぐに事実関係を確認、そしてインターネットを通して削除等の対応をしているところです。それについては積極的に、教育委員会、そして東京都との連携は進めていこうというふうに考えております。","id":"exchange-179"},{"speaker":"伊藤委員","kind":"確認","question":"その中で情報収集１つの手法として、だからやっていただいてありがたいのだけれども、次のステップとしてそれを受け取った後です。つまり、そういうことで具体的に解決していく仕組みになっているのですかということの確認を改めてお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"こちらのほうに連絡が入った時点ですぐに、その日のうちに、ＨＥＡＲＴＳが学校に派遣されます。同時に、各学校で改めて児童生徒に対し、この情報モラルを含めて指導していくというような体制は今後とも進めていこうというふうに考えております。","id":"exchange-180"},{"speaker":"伊藤委員","kind":"質問","question":"児童生徒に貸与するタブレットについてお伺いするのですが、グーグルのアカウントを設定すると、数秒後にわかるメールが来るのです。いじめに関する情報については、そういうところからも取れる可能性があると思うのですが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"今、タブレット推進校で行っていますけれども、それとパソコン教室も含めて、ログは一応取っております。誰がどういうふうにアクセスしたかということは管理をしている状況です。","id":"exchange-181"},{"speaker":"伊藤委員","kind":"質問","question":"ウィンドウズ１０に変えると、ともかくグーグルのアカウントを設定すれば、誰がどの端末からどうアクセスしたかすぐわかるのです。最終的にはいじめの解決につなげていくことをつくり上げていったらいいのではないでしょうかということを質問していますので。","respondent":"有馬学務課長","answer":"そういう意味では、確かに個人情報で誰がどういうふうにインターネットにアクセスするかということは、今タブレットなどは個人持ちでできております。","id":"exchange-182"},{"speaker":"伊藤委員","kind":"意見","question":"そういう中で、いじめに対する情報をつかんで、しかも具体的にそれを解決していく仕組みをつくり上げていく思いと努力と決意を聞かせてください。お願いいたしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"現在、また教員に対する研修も毎年きちんとやりながら、まず使う者がしっかりそのルールを守るということがまず大前提だと思っています。続いて、改めて専門の業者と教育委員会で様々な機会で検討会を持ちまして、十分対応していきたいというふうに考えているところです。","id":"exchange-183"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307926?Template=document&Id=1054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":129386,"voices":442}}]);
